namespace IAFahim.Algebra.GraphPoly
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Tutte
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int Find(int* parent, int i)
        {
            while (parent[i] != i)
            {
                parent[i] = parent[parent[i]];
                i = parent[i];
            }
            return i;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int CountComponents(int n, int edges, int* from, int* to, long mask, int* parent)
        {
            for (int i = 0; i < n; i++) parent[i] = i;
            int comps = n;
            for (int e = 0; e < edges; e++)
                if ((mask & (1L << e)) != 0L)
                {
                    int u = Find(parent, from[e]), v = Find(parent, to[e]);
                    if (u != v) { parent[u] = v; comps--; }
                }
            return comps;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Subset(int n, int edges, int* from, int* to, long x, long y, int MOD)
        {
            long modL = MOD;
            long result = 0L;
            long size = 1L << edges;
            int* parent = stackalloc int[n];

            // Precompute power tables. xExp = rkE - rkA in [0, n-1]; yExp = eCount - rkA in [0, edges].
            long* xPow = stackalloc long[n];
            long* yPow = stackalloc long[edges + 1];
            long xb = x % modL; if (xb < 0L) xb += modL;
            long yb = y % modL; if (yb < 0L) yb += modL;
            xPow[0] = 1L % modL;
            for (int i = 1; i < n; i++) xPow[i] = (xPow[i - 1] * xb) % modL;
            yPow[0] = 1L % modL;
            for (int i = 1; i <= edges; i++) yPow[i] = (yPow[i - 1] * yb) % modL;

            int compsE = CountComponents(n, edges, from, to, size - 1L, parent);
            int rkE = n - compsE;
            for (long mask = 0L; mask < size; mask++)
            {
                int comps = CountComponents(n, edges, from, to, mask, parent);
                int eCount = PopCount(mask);
                int rkA = n - comps;
                int xExp = rkE - rkA;
                int yExp = eCount - rkA;
                long term = (xPow[xExp] * yPow[yExp]) % modL;
                result = (result + term) % modL;
            }
            return result;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int PopCount(long m)
        {
            int c = 0;
            ulong u = (ulong)m;
            while (u != 0UL) { u &= (u - 1UL); c++; }
            return c;
        }
    }
}

namespace IAFahim.Algebra.GraphPoly
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Independence
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool IsIndependentSet(int n, bool* adj, int mask)
        {
            for (int i = 0; i < n; i++)
            {
                if ((mask & (1 << i)) == 0) continue;
                for (int j = i + 1; j < n; j++)
                {
                    if ((mask & (1 << j)) == 0) continue;
                    long index = (long)i * (long)n + (long)j;
                    if (adj[index]) return false;
                }
            }
            return true;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int PopCount(int mask)
        {
            int bits = 0;
            while (mask > 0) { if ((mask & 1) != 0) bits++; mask >>= 1; }
            return bits;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Polynomial(int n, bool* adj, long x, int MOD)
        {
            long* xPowTable = stackalloc long[n + 1];
            xPowTable[0] = 1L;
            for (int i = 1; i <= n; i++) xPowTable[i] = (xPowTable[i - 1] * x) % (long)MOD;

            long result = 0L;
            int size = 1 << n;
            for (int mask = 0; mask < size; mask++)
            {
                if (IsIndependentSet(n, adj, mask))
                {
                    int bits = PopCount(mask);
                    result = (result + xPowTable[bits]) % (long)MOD;
                }
            }
            return result;
        }
    }
}

namespace IAFahim.Algebra.GraphPoly
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Chromatic
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool IsIndependentSet(int n, bool* adj, int mask)
        {
            for (int i = 0; i < n; i++)
            {
                if ((mask & (1 << i)) == 0) continue;
                for (int j = i + 1; j < n; j++)
                {
                    if ((mask & (1 << j)) == 0) continue;
                    long index = (long)i * (long)n + (long)j;
                    if (adj[index]) return false;
                }
            }
            return true;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int PopCount(int mask)
        {
            int bits = 0;
            while (mask > 0)
            {
                if ((mask & 1) != 0) bits++;
                mask >>= 1;
            }
            return bits;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long ModPow(long b, long e, long mod)
        {
            long r = 1L;
            b %= mod;
            if (b < 0L) b += mod;
            while (e > 0L)
            {
                if ((e & 1L) != 0L) r = (r * b) % mod;
                b = (b * b) % mod;
                e /= 2L;
            }
            return r;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void ZetaTransform(int n, int size, int MOD, long* F)
        {
            for (int i = 0; i < n; i++)
            {
                int bit = 1 << i;
                for (int mask = 0; mask < size; mask++)
                {
                    if ((mask & bit) != 0)
                    {
                        F[mask] = (F[mask] + F[mask ^ bit]) % MOD;
                    }
                }
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long AccumulateInclusionExclusion(int n, long sum, long term, int mask, int MOD)
        {
            int pop = PopCount(mask);
            if ((n - pop) % 2 != 0)
            {
                return (sum - term + MOD) % MOD;
            }
            return (sum + term) % MOD;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long EvaluatePointValue(int n, int size, int k, int MOD, long* F)
        {
            long sum = 0L;
            for (int mask = 0; mask < size; mask++)
            {
                long term = ModPow(F[mask], (long)k, MOD);
                sum = AccumulateInclusionExclusion(n, sum, term, mask, MOD);
            }
            return sum;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Subset(int n, bool* adj, int MOD, long* coeffs)
        {
            int size = 1 << n;
            long* F = stackalloc long[size];
            for (int mask = 0; mask < size; mask++)
            {
                F[mask] = IsIndependentSet(n, adj, mask) ? 1L : 0L;
            }

            ZetaTransform(n, size, MOD, F);

            long* y = stackalloc long[n + 1];
            for (int k = 0; k <= n; k++)
            {
                y[k] = EvaluatePointValue(n, size, k, MOD, F);
            }

            Interpolate(n, y, MOD, coeffs);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long ComputeLagrangeDenominator(int n, int i, int MOD)
        {
            long den = 1L;
            for (int j = 0; j <= n; j++)
            {
                if (i != j)
                {
                    long diff = (i - j + MOD) % MOD;
                    den = (den * diff) % MOD;
                }
            }
            return den;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void SyntheticDivide(int polyLen, long* poly, long root, int MOD, long* q)
        {
            long lastQ = 0L;
            for (int j = polyLen - 1; j > 0; j--)
            {
                q[j - 1] = (poly[j] + lastQ * root) % MOD;
                lastQ = q[j - 1];
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void AddScaledQuotient(int polyLen, long* q, long factor, int MOD, long* coeffs)
        {
            for (int j = 0; j < polyLen - 1; j++)
            {
                long add = (q[j] * factor) % MOD;
                coeffs[j] = (coeffs[j] + add) % MOD;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void Interpolate(int n, long* y, int MOD, long* coeffs)
        {
            for (int i = 0; i <= n; i++) coeffs[i] = 0L;

            long* poly = stackalloc long[n + 2];
            poly[0] = 1L;
            for (int i = 1; i <= n + 1; i++) poly[i] = 0L;
            int polyLen = 1;

            for (int i = 0; i <= n; i++)
            {
                long* nextPoly = stackalloc long[polyLen + 1];
                for (int j = 0; j <= polyLen; j++) nextPoly[j] = 0L;

                for (int j = 0; j < polyLen; j++)
                {
                    nextPoly[j + 1] = (nextPoly[j + 1] + poly[j]) % MOD;
                    long sub = (poly[j] * i) % MOD;
                    nextPoly[j] = (nextPoly[j] - sub + MOD) % MOD;
                }
                polyLen++;
                for (int j = 0; j < polyLen; j++) poly[j] = nextPoly[j];
            }

            long* temp = stackalloc long[polyLen];
            long* q = stackalloc long[polyLen];
            long* r = stackalloc long[polyLen];

            for (int i = 0; i <= n; i++)
            {
                long den = ComputeLagrangeDenominator(n, i, MOD);

                long invDen = ModPow(den, MOD - 2, MOD);
                long factor = (y[i] * invDen) % MOD;

                long root = (long)i % MOD;
                SyntheticDivide(polyLen, poly, root, MOD, q);

                AddScaledQuotient(polyLen, q, factor, MOD, coeffs);
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int NumberDp(int n, bool* adj, int MOD)
        {
            long* coeffs = stackalloc long[n + 1];
            Subset(n, adj, MOD, coeffs);

            for (int k = 1; k <= n; k++)
            {
                long val = 0L;
                long xPow = 1L;
                for (int i = 0; i <= n; i++)
                {
                    val = (val + coeffs[i] * xPow) % MOD;
                    xPow = (xPow * (long)k) % MOD;
                }
                if (val > 0L) return k;
            }
            return n;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void DeletionContraction(int n, bool* adj, int edges, int* from, int* to, int MOD, long* coeffs)
        {
            Subset(n, adj, MOD, coeffs);
        }
    }
}

namespace IAFahim.Algebra.GraphPoly
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Matching
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Polynomial(int n, bool* adj, long x, int MOD)
        {
            int size = 1 << n;
            long* dp = stackalloc long[size];
            for (int i = 0; i < size; i++) dp[i] = 0L;
            dp[0] = 1L;

            for (int mask = 1; mask < size; mask++)
            {
                int v = -1;
                for (int i = 0; i < n; i++)
                {
                    if ((mask & (1 << i)) != 0)
                    {
                        v = i;
                        break;
                    }
                }

                int maskWithoutV = mask ^ (1 << v);
                long ways = dp[maskWithoutV];

                for (int u = v + 1; u < n; u++)
                {
                    if ((mask & (1 << u)) != 0 && adj[(long)v * n + u])
                    {
                        int maskWithoutUAndV = maskWithoutV ^ (1 << u);
                        long edgeWays = (dp[maskWithoutUAndV] * x) % MOD;
                        ways = (ways + edgeWays) % MOD;
                    }
                }

                dp[mask] = ways;
            }

            return dp[size - 1];
        }
    }
}

namespace IAFahim.Algebra.GraphPoly
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Reliability
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int Find(int* parent, int i)
        {
            while (parent[i] != i)
            {
                parent[i] = parent[parent[i]];
                i = parent[i];
            }
            return i;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool IsConnected(int n, int edges, int* from, int* to, int mask, int* parent)
        {
            for (int i = 0; i < n; i++) parent[i] = i;
            int components = n;
            for (int e = 0; e < edges; e++)
            {
                if ((mask & (1 << e)) == 0) continue;
                int u = Find(parent, from[e]), v = Find(parent, to[e]);
                if (u != v)
                {
                    parent[u] = v;
                    components--;
                }
            }
            return components == 1;
        }

        public static long Run(int n, int edges, int* from, int* to, long p, int MOD)
        {
            long mod = (long)MOD;
            long q = (1L - p + mod) % mod;

            // Probability of a subgraph depends only on its present-edge count:
            // present edges contribute p, absent edges contribute q=(1-p).
            // Precompute pPow[i]=p^i and qPow[i]=q^i for i in [0,edges].
            long* pPow = stackalloc long[edges + 1];
            long* qPow = stackalloc long[edges + 1];
            pPow[0] = 1L;
            qPow[0] = 1L;
            for (int i = 1; i <= edges; i++)
            {
                pPow[i] = (pPow[i - 1] * p) % mod;
                qPow[i] = (qPow[i - 1] * q) % mod;
            }

            long result = 0L;
            int size = 1 << edges;
            int* parent = stackalloc int[n];
            for (int mask = 0; mask < size; mask++)
            {
                if (IsConnected(n, edges, from, to, mask, parent))
                {
                    int edgeCount = 0;
                    int m = mask;
                    while (m > 0) { m &= m - 1; edgeCount++; }
                    long prob = (pPow[edgeCount] * qPow[edges - edgeCount]) % mod;
                    result = (result + prob) % mod;
                }
            }
            return result;
        }
    }
}

namespace IAFahim.Algebra.GraphPoly
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Rook
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool IsValidPlacement(int n, int m, bool* blocked, long mask, bool* rowUsed, bool* colUsed, out int count)
        {
            count = 0;
            for (int i = 0; i < n; i++) rowUsed[i] = false;
            for (int j = 0; j < m; j++) colUsed[j] = false;

            for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
            {
                int bit = i * m + j;
                if ((mask & (1L << bit)) == 0) continue;
                if (blocked[bit] || rowUsed[i] || colUsed[j]) return false;
                rowUsed[i] = true;
                colUsed[j] = true;
                count++;
            }
            return true;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Run(int n, int m, bool* blocked, long x, int MOD)
        {
            long result = 0L;
            long size = 1L << (n * m);
            bool* rowUsed = stackalloc bool[n];
            bool* colUsed = stackalloc bool[m];
            for (long mask = 0; mask < size; mask++)
            {
                if (IsValidPlacement(n, m, blocked, mask, rowUsed, colUsed, out int count))
                {
                    long xPow = 1L;
                    for (int p = 0; p < count; p++) xPow = (xPow * x) % (long)MOD;
                    result = (result + xPow) % (long)MOD;
                }
            }
            return result;
        }
    }
}

namespace IAFahim.Algebra.Polynomial
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class BerlekampMassey
{
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Run(long* s, int n, int MOD, long* c)
        {
            if (n <= 0)
            {
                c[0] = 1L;
                return 1;
            }

            long* b = stackalloc long[n + 1];
            long* tmp = stackalloc long[n + 1];

            InitArrays(n, c, b, tmp);

            int L = 0;
            int m = 1;
            long b_val = 1L;

            for (int i = 0; i < n; i++)
            {
                long d = CalculateDiscrepancy(s, c, i, L, MOD);

                if (d == 0L)
                {
                    m++;
                    continue;
                }

                CopyArray(c, tmp, n);

                long factor = (d * ModPow(b_val, (long)MOD - 2L, (long)MOD)) % (long)MOD;

                UpdateCoefficients(c, b, factor, L, m, n, MOD);

                if (2 * L <= i)
                {
                    L = i + 1 - L;
                    CopyArray(tmp, b, n);
                    b_val = d;
                    m = 1;
                }
                else
                {
                    m++;
                }
            }

            return L + 1;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void InitArrays(int n, long* c, long* b, long* tmp)
        {
            for (int i = 0; i <= n; i++)
            {
                c[i] = 0L;
                b[i] = 0L;
                tmp[i] = 0L;
            }
            c[0] = 1L;
            b[0] = 1L;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long CalculateDiscrepancy(long* s, long* c, int i, int L, int MOD)
        {
            long d = s[i];
            for (int j = 1; j <= L; j++)
            {
                d = (d + c[j] * s[i - j]) % (long)MOD;
            }
            if (d < 0L)
            {
                d += (long)MOD;
            }
            return d;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void CopyArray(long* src, long* dst, int n)
        {
            for (int j = 0; j <= n; j++)
            {
                dst[j] = src[j];
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void UpdateCoefficients(long* c, long* b, long factor, int L, int m, int n, int MOD)
        {
            for (int j = 0; j <= L; j++)
            {
                int idx = j + m;
                if (idx <= n)
                {
                    long t = c[idx] - (factor * b[j]) % (long)MOD;
                    c[idx] = t + ((t >> 63) & (long)MOD);
                }
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long ModPow(long b, long e, long mod)
        {
            long r = 1L;
            b %= mod;
            if (b < 0L)
            {
                b += mod;
            }
            while (e > 0L)
            {
                if ((e & 1L) != 0L)
                {
                    r = (r * b) % mod;
                }
                b = (b * b) % mod;
                e >>= 1;
            }
            return r;
        }
    }
}

namespace IAFahim.Algebra.Polynomial
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class CantorZassenhaus
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Run(long* poly, int n, int MOD, long* outF, int* outL)
        {
            for (int i = 0; i < n; i++) outF[i] = poly[i];
            outL[0] = n;
            return 1;
        }
    }
}

namespace IAFahim.Algebra.Polynomial
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class PowMod
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Run(long* poly, int lenPoly, long exponent, long* modPoly, int lenModPoly, long* result, out int lenResult, int MOD)
        {
            lenPoly = ComputeEffectiveLength(poly, lenPoly);
            lenModPoly = ComputeEffectiveLength(modPoly, lenModPoly);

            result[0] = 1L;
            lenResult = 1;

            if (exponent == 0L || lenModPoly <= 1)
            {
                if (lenModPoly == 1) lenResult = 0;
                return;
            }

            // After reducing the base modulo modPoly, the reduced base has degree
            // strictly less than deg(modPoly), i.e. length < lenModPoly. Every product
            // formed in the loop then has length <= 2*(lenModPoly-1)-1 = 2*lenModPoly-3,
            // so buffers of size lenModPoly*2+1 are always sufficient.
            // The quotient produced when reducing the (unreduced) initial base can be
            // longer than that, so the scratch buffers must accommodate lenPoly.
            int scratchLen = lenPoly > lenModPoly * 2 + 1 ? lenPoly : lenModPoly * 2 + 1;

            long* basePoly = stackalloc long[scratchLen];
            long* q = stackalloc long[scratchLen];
            long* r = stackalloc long[scratchLen];
            long* temp = stackalloc long[scratchLen];

            // Reduce the base modulo modPoly so its degree is below deg(modPoly).
            int lenBase;
            int lenQInit;
            DivMod.Run(poly, lenPoly, modPoly, lenModPoly, q, out lenQInit, basePoly, out lenBase, MOD);

            if (lenBase == 0)
            {
                // Base is congruent to 0 modulo modPoly; result is 0 for exponent >= 1.
                lenResult = 0;
                return;
            }

            while (exponent > 0L)
            {
                if ((exponent & 1L) == 1L)
                {
                    ToomCook.Multiply(result, lenResult, basePoly, lenBase, temp, MOD);
                    int tempLen = ComputeEffectiveLength(temp, lenResult + lenBase - 1);

                    int lenQ, lenR;
                    DivMod.Run(temp, tempLen, modPoly, lenModPoly, q, out lenQ, r, out lenR, MOD);

                    CopyArray(r, result, lenR);
                    lenResult = lenR;
                }

                exponent >>= 1;
                if (exponent == 0L) break;

                ToomCook.Multiply(basePoly, lenBase, basePoly, lenBase, temp, MOD);
                int tempLen2 = ComputeEffectiveLength(temp, lenBase + lenBase - 1);

                int lenQ2, lenR2;
                DivMod.Run(temp, tempLen2, modPoly, lenModPoly, q, out lenQ2, r, out lenR2, MOD);

                CopyArray(r, basePoly, lenR2);
                lenBase = lenR2;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void CopyArray(long* src, long* dst, int len)
        {
            for (int i = 0; i < len; i++)
            {
                dst[i] = src[i];
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int ComputeEffectiveLength(long* poly, int maxLen)
        {
            int len = maxLen;
            while (len > 0 && poly[len - 1] == 0L)
            {
                len--;
            }
            return len;
        }
    }
}

namespace IAFahim.Algebra.Polynomial
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class SquareFree
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Factor(long* poly, int n, int MOD, long* outFact, int* outLens)
        {
            int lenPoly = ComputeEffectiveLength(poly, n);
            if (lenPoly <= 1) return 0;

            long* deriv = stackalloc long[lenPoly];
            for (int i = 1; i < lenPoly; i++)
            {
                deriv[i - 1] = ((long)i % (long)MOD * poly[i]) % (long)MOD;
            }
            int dLen = ComputeEffectiveLength(deriv, lenPoly - 1);

            if (dLen == 0)
            {
                // f(x) = h(x^p), we'd need to take p-th roots. 
                // For completeness, outputting as is since p-th root is complex without full GF logic.
                CopyArray(poly, outFact, lenPoly);
                outLens[0] = lenPoly;
                return 1;
            }

            long* g = stackalloc long[lenPoly];
            int lenG;
            Gcd.Run(poly, lenPoly, deriv, dLen, g, out lenG, MOD);

            long* w = stackalloc long[lenPoly];
            int lenW;
            long* r = stackalloc long[lenPoly];
            DivMod.Run(poly, lenPoly, g, lenG, w, out lenW, r, out int lenR, MOD);

            CopyArray(w, outFact, lenW);
            outLens[0] = lenW;

            // w is the product of all distinct irreducible factors of f.
            // Further multiplicity extraction can be added here if needed.
            return 1;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void CopyArray(long* src, long* dst, int len)
        {
            for (int i = 0; i < len; i++) dst[i] = src[i];
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int ComputeEffectiveLength(long* poly, int maxLen)
        {
            int len = maxLen;
            while (len > 0 && poly[len - 1] == 0L)
            {
                len--;
            }
            return len;
        }
    }
}

namespace IAFahim.Algebra.Polynomial
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class RootFind
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Find(long* poly, int n, int MOD, long* roots)
        {
            int count = 0;
            for (long x = 0; x < MOD && count < n; x++)
            {
                if (EvaluatePolynomial(poly, n, x, MOD) == 0) 
                    roots[count++] = x;
            }
            return count;
        }

        private static long EvaluatePolynomial(long* poly, int n, long x, int MOD)
        {
            long val = 0;
            long xPow = 1;
            for (int i = 0; i < n; i++)
            {
                val = (val + poly[i] * xPow) % MOD;
                xPow = xPow * x % MOD;
            }
            return val;
        }
    }
}

