namespace IAFahim.Algebra.Polynomial
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class ProductTree
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Build(long* values, int n, int MOD, long* tree, int* offsets, int* sizes)
        {
            int nodeCount = 0;
            for (int i = 0; i < n; i++)
            {
                offsets[nodeCount] = i * 2;
                sizes[nodeCount] = 2;
                tree[i * 2] = (MOD - values[i] % MOD) % MOD;
                tree[i * 2 + 1] = 1;
                nodeCount++;
            }
            int levelStart = 0;
            int levelSize = n;
            int writeOff = n * 2;
            while (levelSize > 1)
            {
                int nextStart = nodeCount;
                int nextSize = 0;
                BuildLevel(tree, offsets, sizes, levelStart, levelSize, ref nodeCount, ref writeOff, ref nextSize, MOD);
                levelStart = nextStart;
                levelSize = nextSize;
            }
            return nodeCount;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void BuildLevel(long* tree, int* offsets, int* sizes, int levelStart, int levelSize, ref int nodeCount, ref int writeOff, ref int nextSize, int MOD)
        {
            for (int i = 0; i < levelSize; i += 2)
            {
                if (i + 1 < levelSize)
                {
                    offsets[nodeCount] = writeOff;
                    int sa = sizes[levelStart + i], sb = sizes[levelStart + i + 1];
                    int sr = sa + sb - 1;
                    sizes[nodeCount] = sr;
                    ToomCook.Multiply(
                        tree + offsets[levelStart + i], sa,
                        tree + offsets[levelStart + i + 1], sb,
                        tree + writeOff, MOD);
                    writeOff += sr;
                    nodeCount++;
                    nextSize++;
                }
                else
                {
                    offsets[nodeCount] = offsets[levelStart + i];
                    sizes[nodeCount] = sizes[levelStart + i];
                    nodeCount++;
                    nextSize++;
                }
            }
        }
    }
}

namespace IAFahim.Algebra.Polynomial
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Ntt
    {
        private const long MOD1 = 998244353L;
        private const long MOD2 = 985661441L;
        private const long MOD3 = 754974721L;

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Convolve(long* a, long* b, long* result, int n, int MOD, long primRoot)
        {
            ToomCook.Multiply(a, n, b, n, result, MOD);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void ThreePrime(long* a, long* b, long* result, int n)
        {
            ToomCook.Multiply(a, n, b, n, result, (int)MOD1);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Crt(long* r1, long* r2, long* r3, long* result, int n, int MOD)
        {
            long m1 = MOD1, m2 = MOD2, m3 = MOD3;
            long m12 = m1 * m2;
            long inv1 = ModPow(m1 % m2, m2 - 2L, m2);
            long inv12 = ModPow(m12 % m3, m3 - 2L, m3);
            for (int i = 0; i < n; i++)
            {
                long a1 = r1[i], a2 = r2[i], a3 = r3[i];
                long k2 = ((a2 - a1 % m2 + m2) % m2 * inv1) % m2;
                long a12 = a1 + m1 * k2;
                long k3 = ((a3 - a12 % m3 + m3) % m3 * inv12) % m3;
                result[i] = (a12 + (m12 % (long)MOD) * k3) % (long)MOD;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long ModPow(long b, long e, long mod)
        {
            long r = 1L; b %= mod; if (b < 0L) b += mod;
            while (e > 0L) { if ((e & 1L) != 0L) r = (r * b) % mod; b = (b * b) % mod; e >>= 1; }
            return r;
        }
    }
}

namespace IAFahim.Algebra.Polynomial
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class RationalInterpolation
    {
        private const long NonInvertible = -1L;

        // Computes a rational interpolant R(x) = num(x) / den(x) passing through
        // the n points (xs[i], ys[i]) over the prime field Z/MOD via Thiele's
        // continued fraction. The continued-fraction coefficients are converted
        // into explicit numerator/denominator polynomials using the convergent
        // recurrence P_k = a_k*P_{k-1} + (x - x_{k-1})*P_{k-2}.
        //
        // Coefficients are written little-endian (index = power of x), reduced
        // into [0, MOD). Numerator degree is n/2, denominator degree is (n-1)/2,
        // so caller buffers num/den of length n are always large enough.
        // Returns the numerator length (degNum + 1), or 0 if n == 0.
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Run(long* xs, long* ys, int n, long MOD, long* num, long* den)
        {
            if (n == 0) return 0;

            // Thiele continued-fraction coefficients a[0..n-1].
            long* a = stackalloc long[n];
            ThieleInterpolation(xs, ys, n, a, MOD);

            // Reduce node abscissae once into [0, MOD) for the polynomial recurrence.
            long* xr = stackalloc long[n];
            for (int i = 0; i < n; i++)
            {
                long v = xs[i] % MOD;
                if (v < 0) v += MOD;
                xr[i] = v;
            }

            // Convergent recurrence. P holds numerator polynomials, Q denominators.
            // pPrev/qPrev = convergent k-1, pPrev2/qPrev2 = convergent k-2.
            // Initial: P_{-1} = 1, Q_{-1} = 0, P_0 = a[0], Q_0 = 1.
            long* pPrev2 = stackalloc long[n];
            long* qPrev2 = stackalloc long[n];
            long* pPrev = stackalloc long[n];
            long* qPrev = stackalloc long[n];
            long* pCur = stackalloc long[n];
            long* qCur = stackalloc long[n];

            for (int i = 0; i < n; i++)
            {
                pPrev2[i] = 0; qPrev2[i] = 0;
                pPrev[i] = 0; qPrev[i] = 0;
            }
            pPrev2[0] = 1L;              // P_{-1} = 1
            // Q_{-1} = 0 (already zeroed)
            long a0 = a[0] % MOD;
            if (a0 < 0) a0 += MOD;
            pPrev[0] = a0;              // P_0 = a[0]
            qPrev[0] = 1L;             // Q_0 = 1

            int degPPrev2 = 0;          // degree of P_{-1}
            int degQPrev2 = -1;         // Q_{-1} = 0 has no nonzero term
            int degPPrev = 0;           // degree of P_0
            int degQPrev = 0;           // degree of Q_0

            for (int k = 1; k < n; k++)
            {
                long ak = a[k] % MOD;
                if (ak < 0) ak += MOD;
                long xk1 = xr[k - 1];   // x_{k-1}, already in [0, MOD)

                int degPCur = ConvergentStep(pPrev, degPPrev, pPrev2, degPPrev2, ak, xk1, pCur, MOD);
                int degQCur = ConvergentStep(qPrev, degQPrev, qPrev2, degQPrev2, ak, xk1, qCur, MOD);

                // Shift: (k-1) <- (k-2), k <- (k-1) by rotating buffers.
                long* tp = pPrev2; pPrev2 = pPrev; pPrev = pCur; pCur = tp;
                long* tq = qPrev2; qPrev2 = qPrev; qPrev = qCur; qCur = tq;
                degPPrev2 = degPPrev; degPPrev = degPCur;
                degQPrev2 = degQPrev; degQPrev = degQCur;
            }

            // After the loop pPrev/qPrev hold the final convergents P_{n-1}/Q_{n-1}.
            int degNum = n / 2;
            int degDen = (n - 1) / 2;
            for (int i = 0; i <= degNum; i++) num[i] = pPrev[i];
            for (int i = 0; i <= degDen; i++) den[i] = qPrev[i];

            return degNum + 1;
        }

        // dst = ak * prev + (x - xk1) * prev2, all coefficients in [0, MOD).
        // prev has degree degPrev, prev2 has degree degPrev2 (-1 means zero poly).
        // Returns the degree of dst (0 if dst is the zero polynomial).
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int ConvergentStep(long* prev, int degPrev, long* prev2, int degPrev2, long ak, long xk1, long* dst, long MOD)
        {
            // Multiplying prev2 (degree degPrev2) by (x - xk1) raises its degree by one.
            int shiftedDeg = degPrev2 < 0 ? -1 : degPrev2 + 1;
            int top = degPrev > shiftedDeg ? degPrev : shiftedDeg;
            if (top < 0) top = 0;

            long negX = MOD - xk1;      // -x_{k-1} mod MOD, in [1, MOD] (==MOD only if xk1==0)
            if (negX == MOD) negX = 0;

            for (int i = 0; i <= top; i++)
            {
                dst[i] = ConvergentCoefficient(prev, degPrev, prev2, degPrev2, ak, negX, i, MOD);
            }

            int deg = top;
            while (deg > 0 && dst[deg] == 0L) deg--;
            return deg;
        }

        // Single coefficient of dst = ak * prev + (x - xk1) * prev2 at power i.
        // negX is (-xk1) mod MOD; result is reduced into [0, MOD).
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long ConvergentCoefficient(long* prev, int degPrev, long* prev2, int degPrev2, long ak, long negX, int i, long MOD)
        {
            long acc = 0L;

            // ak * prev[i]
            if (i <= degPrev)
            {
                acc = ak * prev[i] % MOD;
            }

            // (x - xk1) * prev2 contributes prev2[i-1] (from the x factor)
            // and (-xk1) * prev2[i] (from the constant factor).
            if (i >= 1 && (i - 1) <= degPrev2 && degPrev2 >= 0)
            {
                acc += prev2[i - 1];
                if (acc >= MOD) acc -= MOD;
            }
            if (i <= degPrev2 && degPrev2 >= 0 && negX != 0L)
            {
                acc += negX * prev2[i] % MOD;
                if (acc >= MOD) acc -= MOD;
            }

            return acc;
        }

        // Fills a[0..n-1] with the Thiele continued-fraction (reciprocal-difference)
        // coefficients for the points (x[i], y[i]) over Z/MOD. y is treated as
        // read-only; the working columns are kept in private scratch buffers.
        //
        // Uses the reciprocal (inverse) difference recurrence
        //   rho_{-1}        = 0
        //   rho_0(x_i)      = y_i
        //   rho_k(x_i..x_{i+k}) = rho_{k-2}(x_{i+1}..x_{i+k-1})
        //                         + (x_i - x_{i+k}) / (rho_{k-1}(x_i..) - rho_{k-1}(x_{i+1}..))
        // and sets the continued-fraction coefficient
        //   a[k] = rho_k(x_0..x_k) - rho_{k-2}(x_0..x_{k-2})
        // (with rho_{-1} = rho_{-2} = 0).
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void ThieleInterpolation(long* x, long* y, int n, long* a, long MOD)
        {
            // Reduce abscissae once into [0, MOD).
            long* xr = stackalloc long[n];
            for (int i = 0; i < n; i++)
            {
                long v = x[i] % MOD;
                if (v < 0) v += MOD;
                xr[i] = v;
            }

            // prevPrev = column k-2 (rho_{-1} = 0 initially),
            // prev     = column k-1 (rho_0 = y initially).
            long* prevPrev = stackalloc long[n];
            long* prev = stackalloc long[n];
            long* cur = stackalloc long[n];
            for (int i = 0; i < n; i++)
            {
                prevPrev[i] = 0L;
                long v = y[i] % MOD;
                if (v < 0) v += MOD;
                prev[i] = v;
            }

            a[0] = prev[0];
            for (int k = 1; k < n; k++)
            {
                int count = n - k;          // number of entries in column k
                for (int i = 0; i < count; i++)
                {
                    cur[i] = ReciprocalDifference(prev, prevPrev, xr, i, k, MOD);
                }

                // Continued-fraction coefficient: subtract rho_{k-2}(x_0..x_{k-2}),
                // which is the head of the prevPrev column.
                long coeff = cur[0] - prevPrev[0];
                if (coeff < 0) coeff += MOD;
                a[k] = coeff;

                // Advance the rolling columns: prevPrev <- prev <- cur.
                long* tmp = prevPrev;
                prevPrev = prev;
                prev = cur;
                cur = tmp;
            }
        }

        // One reciprocal-difference entry of column k at row i:
        //   rho_{k-2}(x_{i+1}..) + (x_i - x_{i+k}) / (rho_{k-1}(x_i) - rho_{k-1}(x_{i+1}))
        // reduced into [0, MOD). prev is column k-1, prevPrev is column k-2.
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long ReciprocalDifference(long* prev, long* prevPrev, long* xr, int i, int k, long MOD)
        {
            long denom = (prev[i] - prev[i + 1]) % MOD;
            if (denom < 0) denom += MOD;
            long inv = ModInv(denom, MOD);

            long xdiff = (xr[i] - xr[i + k]) % MOD;
            if (xdiff < 0) xdiff += MOD;

            long term = xdiff * inv % MOD;
            long val = prevPrev[i + 1] + term;
            if (val >= MOD) val -= MOD;
            return val;
        }

        // Modular inverse of a mod MOD via the extended Euclidean algorithm.
        // a may be any (possibly negative) value; it is reduced into [0, MOD)
        // first. Returns the inverse in [0, MOD), or NonInvertible (-1) when a
        // is not coprime to MOD (e.g. a == 0).
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long ModInv(long a, long MOD)
        {
            long t = 0, newT = 1;
            long r = MOD, newR = a % MOD;
            if (newR < 0) newR += MOD;
            while (newR != 0)
            {
                long q = r / newR;
                long tmpT = t - q * newT;
                long tmpR = r - q * newR;
                t = newT; r = newR;
                newT = tmpT; newR = tmpR;
            }
            if (r > 1) return NonInvertible;
            if (t < 0) t += MOD;
            return t;
        }
    }
}

namespace IAFahim.Algebra.Polynomial
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Berlekamp
    {
        private const int NoPivotColumn = -1;

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Run(long* poly, int n, int MOD, long* outF, int* outL)
        {
            if (n <= 1)
            {
                CopyPoly(poly, outF, n);
                outL[0] = n;
                return 1;
            }

            long byteCount = (long)n * (long)n;
            long* Q = stackalloc long[(int)byteCount];
            BuildQMatrix(poly, n, MOD, Q);
            int rank = ReduceQMatrix(Q, n, MOD);
            return ExtractBasis(poly, Q, n, rank, MOD, outF, outL);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void CopyPoly(long* src, long* dst, int n)
        {
            for (int i = 0; i < n; i++) dst[i] = src[i];
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void BuildQMatrix(long* poly, int n, int MOD, long* Q)
        {
            long nn = (long)n * (long)n;
            for (long i = 0L; i < nn; i++) Q[i] = 0L;

            long* tmp = stackalloc long[n];
            for (int i = 0; i < n; i++)
            {
                long index = (long)i * (long)n + (long)i;
                Q[index] = 1L;
            }

            for (int i = 0; i < n; i++)
            {
                long index = (long)i * (long)n;
                Q[index] = (Q[index] - 1L + (long)MOD) % (long)MOD;
            }

            for (int i = 0; i < n; i++)
            {
                for (int j = 0; j < n; j++) tmp[j] = 0L;
                for (int j = 0; j < n; j++)
                {
                    long qIdx = (long)j * (long)n + (long)i;
                    tmp[i] = (tmp[i] + Q[qIdx]) % (long)MOD;
                }
                for (int j = 0; j < n; j++)
                {
                    long qIdx = (long)i * (long)n + (long)j;
                    Q[qIdx] = tmp[j];
                }
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int FindPivotRow(long* Q, int n, int startRow, int col)
        {
            int row = startRow;
            int rowBase = row * n + col;
            while (row < n)
            {
                if (Q[rowBase] != 0L) break;
                row++;
                rowBase += n;
            }
            return row;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void NormalizePivotRow(long* Q, int n, int pivotRow, long inv, long mod)
        {
            long* rankRow = Q + pivotRow * n;
            for (int j = 0; j < n; j++)
                rankRow[j] = (rankRow[j] * inv) % mod;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void EliminateOtherRows(long* Q, int n, int pivotRow, int col, long mod)
        {
            long* rankRow = Q + pivotRow * n;
            for (int r = 0; r < n; r++)
            {
                int rBase = r * n;
                if (r != pivotRow && Q[rBase + col] != 0L)
                {
                    long factor = Q[rBase + col];
                    long* curRow = Q + rBase;
                    for (int j = 0; j < n; j++)
                    {
                        long t = curRow[j] - (factor * rankRow[j]) % mod;
                        t += (t >> 63) & mod;
                        curRow[j] = t;
                    }
                }
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int ReduceQMatrix(long* Q, int n, int MOD)
        {
            long mod = (long)MOD;
            int rank = 0;
            for (int col = 0; col < n && rank < n; col++)
            {
                int row = FindPivotRow(Q, n, rank, col);
                if (row == n) continue;
                if (row != rank) SwapRows(Q, n, rank, row);
                long inv = ModInv(Q[rank * n + col], mod);
                NormalizePivotRow(Q, n, rank, inv, mod);
                EliminateOtherRows(Q, n, rank, col, mod);
                rank++;
            }
            return rank;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void SwapRows(long* Q, int n, int r1, int r2)
        {
            long* row1 = Q + r1 * n;
            long* row2 = Q + r2 * n;
            for (int j = 0; j < n; j++)
            {
                long tmpVal = row1[j];
                row1[j] = row2[j];
                row2[j] = tmpVal;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void MarkPivotColumns(long* Q, int n, int rank, int* pivotColOfRow, byte* isPivotCol)
        {
            for (int c = 0; c < n; c++) isPivotCol[c] = 0;
            for (int r = 0; r < rank; r++)
            {
                long rowBase = (long)r * (long)n;
                int pivotCol = NoPivotColumn;
                for (int c = 0; c < n; c++)
                {
                    if (Q[rowBase + c] != 0L)
                    {
                        pivotCol = c;
                        break;
                    }
                }
                pivotColOfRow[r] = pivotCol;
                if (pivotCol >= 0) isPivotCol[pivotCol] = 1;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void BuildBasisVector(long* Q, int n, int rank, int freeCol, int* pivotColOfRow, long mod, long* basis)
        {
            for (int j = 0; j < n; j++) basis[j] = 0L;
            basis[freeCol] = 1L;
            for (int r = 0; r < rank; r++)
            {
                int pivotCol = pivotColOfRow[r];
                if (pivotCol < 0) continue;
                long coeff = Q[(long)r * (long)n + (long)freeCol] % mod;
                if (coeff != 0L) coeff = mod - coeff;
                basis[pivotCol] = coeff;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int ExtractBasis(long* poly, long* Q, int n, int rank, int MOD, long* outF, int* outL)
        {
            // Q is in reduced row-echelon form. Identify the pivot column of each
            // pivot row and mark every column as pivot or free. The null space of Q
            // (vectors v with Q v = 0) has dimension n - rank, with one basis vector
            // per free column.
            int* pivotColOfRow = stackalloc int[rank];
            byte* isPivotCol = stackalloc byte[n];
            long mod = (long)MOD;
            MarkPivotColumns(Q, n, rank, pivotColOfRow, isPivotCol);

            int factorCount = 0;
            long* basis = stackalloc long[n];
            for (int freeCol = 0; freeCol < n; freeCol++)
            {
                if (isPivotCol[freeCol] != 0) continue;
                BuildBasisVector(Q, n, rank, freeCol, pivotColOfRow, mod, basis);
                for (int j = 0; j < n; j++) outF[(long)factorCount * (long)n + (long)j] = basis[j];
                outL[factorCount++] = n;
            }

            if (factorCount == 0)
            {
                CopyPoly(poly, outF, n);
                outL[0] = n;
                return 1;
            }
            return factorCount;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long ModInv(long a, long mod)
        {
            long b = mod, u = 1L, v = 0L;
            while (b > 0L)
            {
                long t = a / b;
                a -= t * b; long tmp = a; a = b; b = tmp;
                u -= t * v; tmp = u; u = v; v = tmp;
            }
            u %= mod;
            if (u < 0L) u += mod;
            return u;
        }
    }
}

namespace IAFahim.Algebra.Polynomial
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class DivMod
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Run(long* a, int lenA, long* b, int lenB, long* q, out int lenQ, long* r, out int lenR, int MOD)
        {
            lenA = ComputeEffectiveLength(a, lenA);
            lenB = ComputeEffectiveLength(b, lenB);

            if (lenB == 0)
            {
                lenQ = 0;
                lenR = 0;
                return;
            }

            if (lenA < lenB)
            {
                lenQ = 0;
                CopyArray(a, r, lenA);
                lenR = lenA;
                return;
            }

            lenQ = lenA - lenB + 1;
            for (int i = 0; i < lenQ; i++)
            {
                q[i] = 0L;
            }

            long* temp = stackalloc long[lenA];
            CopyArray(a, temp, lenA);

            long inv = ModInv(b[lenB - 1], (long)MOD);

            for (int i = lenA - 1; i >= lenB - 1; i--)
            {
                if (temp[i] == 0L) continue;

                long q_i = (temp[i] * inv) % (long)MOD;
                q[i - (lenB - 1)] = q_i;

                for (int j = 0; j < lenB; j++)
                {
                    long sub = (q_i * b[j]) % (long)MOD;
                    temp[i - (lenB - 1) + j] = (temp[i - (lenB - 1) + j] - sub + (long)MOD) % (long)MOD;
                }
            }

            lenR = ComputeEffectiveLength(temp, lenB - 1);
            CopyArray(temp, r, lenR);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void CopyArray(long* src, long* dst, int len)
        {
            for (int i = 0; i < len; i++)
            {
                dst[i] = src[i];
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int ComputeEffectiveLength(long* poly, int maxLen)
        {
            int len = maxLen;
            while (len > 0 && poly[len - 1] == 0L)
            {
                len--;
            }
            return len;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long ModInv(long a, long mod)
        {
            long b = mod, u = 1L, v = 0L;
            while (b > 0L)
            {
                long t = a / b;
                a -= t * b;
                long tmp = a;
                a = b;
                b = tmp;

                u -= t * v;
                tmp = u;
                u = v;
                v = tmp;
            }
            u %= mod;
            if (u < 0L) u += mod;
            return u;
        }
    }
}

namespace IAFahim.Algebra.Polynomial
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Gcd
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Run(long* a, int lenA, long* b, int lenB, long* gcd, out int lenGcd, int MOD)
        {
            int maxLen = Math.Max(lenA, lenB);

            long* u = stackalloc long[maxLen];
            long* v = stackalloc long[maxLen];

            CopyArray(a, u, lenA);
            CopyArray(b, v, lenB);

            int lenU = ComputeEffectiveLength(u, lenA);
            int lenV = ComputeEffectiveLength(v, lenB);

            long* q = stackalloc long[maxLen + 1];
            long* r = stackalloc long[maxLen + 1];

            while (lenV > 0)
            {
                int lenQ, lenR;
                DivMod.Run(u, lenU, v, lenV, q, out lenQ, r, out lenR, MOD);

                CopyArray(v, u, lenV);
                lenU = lenV;

                CopyArray(r, v, lenR);
                lenV = lenR;
            }

            if (lenU > 0)
            {
                long mod = (long)MOD;
                long inv = ModInv(u[lenU - 1], mod);
                for (int i = 0; i < lenU; i++)
                {
                    gcd[i] = (u[i] * inv) % mod;
                }
            }
            lenGcd = lenU;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void CopyArray(long* src, long* dst, int len)
        {
            for (int i = 0; i < len; i++)
            {
                dst[i] = src[i];
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int ComputeEffectiveLength(long* poly, int maxLen)
        {
            int len = maxLen;
            while (len > 0 && poly[len - 1] == 0L)
            {
                len--;
            }
            return len;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long ModInv(long a, long mod)
        {
            long b = mod, u = 1L, v = 0L;
            while (b > 0L)
            {
                long t = a / b;
                long na = a - t * b;
                a = b;
                b = na;

                long nu = u - t * v;
                u = v;
                v = nu;
            }
            u %= mod;
            if (u < 0L) u += mod;
            return u;
        }
    }
}

namespace IAFahim.Algebra.Polynomial
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class BostanMori
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Run(long* p, int pLen, long* q, int qLen, long k, int MOD)
        {
            long mod = (long)MOD;

            // The numerator length may grow up to qLen after the first halving step
            // (Bostan-Mori keeps a proper fraction: deg(P) < deg(Q)), while the
            // denominator length stays fixed at qLen across every iteration.
            // Size the scratch buffers once to the worst-case product length:
            //   U = P * Q(-x)  -> max(pLen, qLen) + qLen - 1 coefficients
            //   V = Q * Q(-x)  -> 2*qLen - 1 coefficients
            // both of which fit in 2*sz entries with sz = max(pLen, qLen).
            int sz = Math.Max(pLen, qLen);
            long* qneg = stackalloc long[qLen];
            long* r = stackalloc long[sz * 2];
            long* s = stackalloc long[sz * 2];
            // Dedicated numerator scratch. The caller's p buffer only has pLen
            // capacity, but the rebuilt proper-fraction numerator has up to qLen
            // coefficients, so it would overflow p when pLen < qLen. Write the new
            // numerator here instead and read it back on the next iteration.
            long* num = stackalloc long[qLen];

            // Current numerator: starts as the caller's p (length pLen), then lives
            // in num (length qLen) after the first halving step.
            long* curNum = p;
            int nLen = pLen;

            while (k > 0L)
            {
                for (int i = 0; i < qLen; i++)
                    qneg[i] = ((i & 1) == 0) ? q[i] : (mod - q[i]) % mod;

                // U(x) = P(x) * Q(-x), V(x) = Q(x) * Q(-x)
                ToomCook.Multiply(curNum, nLen, qneg, qLen, r, MOD);
                ToomCook.Multiply(q, qLen, qneg, qLen, s, MOD);

                int uLen = nLen + qLen - 1; // valid coefficients written into r
                int vLen = qLen + qLen - 1; // valid coefficients written into s

                // New numerator = even/odd part of U (parity = k & 1); the proper
                // fraction guarantees it has at most qLen coefficients. Multiply has
                // already fully consumed curNum into r, so writing num is safe even
                // when curNum == num.
                FilterPolynomial(num, qLen, r, (int)(k & 1L), uLen);
                // New denominator = even part of V; exactly qLen coefficients. q has
                // qLen capacity, so writing qLen coefficients back into q is in bounds.
                FilterPolynomial(q, qLen, s, 0, vLen);

                curNum = num;
                nLen = qLen;
                k >>= 1;
            }

            // [x^0] P/Q = P(0) / Q(0) = curNum[0] * inv(q[0]) (mod MOD).
            long numerator = curNum[0] % mod;
            if (numerator < 0L) numerator += mod;
            long result = (numerator * ModInv(q[0] % mod, mod)) % mod;
            if (result < 0L) result += mod;
            return result;
        }

        // Writes dstLen coefficients of the (parity)-shifted even/odd part of src:
        // dst[i] = src[parity + 2*i] when that index lies inside the srcLen valid
        // coefficients produced by ToomCook.Multiply, otherwise 0.
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void FilterPolynomial(long* dst, int dstLen, long* src, int parity, int srcLen)
        {
            int idx = parity;
            for (int i = 0; i < dstLen; i++)
            {
                dst[i] = (idx < srcLen) ? src[idx] : 0L;
                idx += 2;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long ModInv(long a, long mod)
        {
            long b = mod, u = 1L, v = 0L;
            while (b > 0L)
            {
                long t = a / b;
                a -= t * b;
                long tmp = a;
                a = b;
                b = tmp;

                u -= t * v;
                tmp = u;
                u = v;
                v = tmp;
            }
            u %= mod;
            if (u < 0L) u += mod;
            return u;
        }
    }
}

