namespace IAFahim.Algebra.Sequence
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Transform
    {
        public static void Binomial(long* a, int n, int MOD, long* b)
        {
            long mod = (long)MOD;
            long* inv = stackalloc long[n < 1 ? 1 : n];
            FillModInverses(inv, n - 1, mod);
            for (int n2 = 0; n2 < n; n2++)
            {
                b[n2] = ComputeBinomialTerm(a, n2, mod, inv);
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long ComputeBinomialTerm(long* a, int n2, long mod, long* inv)
        {
            long sum = 0L;
            long comb = 1L;
            for (int k = 0; k <= n2; k++)
            {
                sum = (sum + comb * a[k]) % mod;
                if (k < n2)
                    comb = (comb * (long)(n2 - k)) % mod * inv[k + 1] % mod;
            }
            return sum;
        }

        public static void InverseBinomial(long* a, int n, int MOD, long* b)
        {
            long mod = (long)MOD;
            long* inv = stackalloc long[n < 1 ? 1 : n];
            FillModInverses(inv, n - 1, mod);
            for (int n2 = 0; n2 < n; n2++)
            {
                b[n2] = ComputeInverseBinomialTerm(a, n2, mod, inv);
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long ComputeInverseBinomialTerm(long* a, int n2, long mod, long* inv)
        {
            long sum = 0L;
            long comb = 1L;
            // sign = (-1)^(n2 - k). Starting at k = 0 it is (-1)^n2; it toggles each step.
            long sign = ((n2 & 1) == 0) ? 1L : mod - 1L;
            for (int k = 0; k <= n2; k++)
            {
                sum = (sum + (sign * comb) % mod * a[k]) % mod;
                if (k < n2)
                    comb = (comb * (long)(n2 - k)) % mod * inv[k + 1] % mod;
                sign = mod - sign;
            }
            return sum;
        }

        public static long SetPartition(int n, int MOD)
        {
            long mod = (long)MOD;
            long* bell = stackalloc long[n + 1];
            long* inv = stackalloc long[n + 1];
            FillModInverses(inv, n, mod);
            bell[0] = 1L;
            for (int i = 1; i <= n; i++)
            {
                bell[i] = 0L;
                long binom = 1L;
                for (int k = 0; k < i; k++)
                {
                    bell[i] = (bell[i] + binom * bell[k]) % mod;
                    binom = (binom * (long)(i - 1 - k)) % mod * inv[k + 1] % mod;
                }
            }
            return bell[n];
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long CayleyCount(int n, int MOD)
        {
            if (n <= 1) return 1L;
            if (n == 2) return 1L;
            return Combinatorial.ModPow((long)n, (long)(n - 2), (long)MOD);
        }

        // Linear sieve of modular inverses: fills inv[1..maxIndex] with the modular
        // inverse of each integer. Valid when mod is prime and mod > maxIndex (the same
        // primality precondition the Fermat-based ModPow already assumes), which guarantees
        // mod % i != 0 so every i in 1..maxIndex is invertible. O(maxIndex) total.
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void FillModInverses(long* inv, int maxIndex, long mod)
        {
            if (maxIndex < 1) return;
            inv[1] = 1L;
            for (int i = 2; i <= maxIndex; i++)
            {
                inv[i] = (mod - (mod / i) * inv[mod % i] % mod) % mod;
            }
        }
    }
}

namespace IAFahim.Algebra.Sequence
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Combinatorial
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Eulerian(int n, int k, int MOD)
        {
            if (n <= 0) return 0L;
            if (k < 0 || k >= n) return 0L;
            if (k == 0) return 1L;

            long* dp = stackalloc long[k + 1];
            long* ndp = stackalloc long[k + 1];
            for (int i = 0; i <= k; i++) { dp[i] = 0L; ndp[i] = 0L; }
            dp[0] = 1L;

            for (int i = 1; i < n; i++)
            {
                int nextN = i + 1;
                for (int j = 0; j <= Math.Min(k, nextN); j++)
                {
                    long val = (j + 1) * dp[j];
                    if (j > 0) val = (val + (long)(nextN - j) * dp[j - 1]) % MOD;
                    ndp[j] = val % MOD;
                }
                for (int j = 0; j <= Math.Min(k, nextN); j++) dp[j] = ndp[j];
            }
            return dp[k] % MOD;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Narayana(int n, int k, int MOD)
        {
            if (k <= 0 || k > n) return 0L;
            long c1 = Binom(n, k, MOD);
            long c2 = Binom(n, k - 1, MOD);
            long invN = ModPow(n, MOD - 2, MOD);
            return c1 * c2 % MOD * invN % MOD;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Lah(int n, int k, int MOD)
        {
            if (k > n || k <= 0) return 0L;
            long nf = Factorial(n, MOD);
            long kf = Factorial(k, MOD);
            long bin = Binom(n - 1, k - 1, MOD);
            return (nf * ModPow(kf, MOD - 2, MOD)) % MOD * bin % MOD;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long YoungTableaux(int* shape, int len, int MOD)
        {
            int n = 0;
            for (int i = 0; i < len; i++) n += shape[i];
            long result = Factorial(n, MOD);
            for (int i = 0; i < len; i++)
            for (int j = 0; j < shape[i]; j++)
            {
                int hook = shape[i] - j;
                for (int ii = i + 1; ii < len && shape[ii] > j; ii++) hook++;
                result = (result * ModPow(hook, MOD - 2, MOD)) % MOD;
            }
            return result;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long HookLength(int* shape, int len, int MOD) => YoungTableaux(shape, len, MOD);

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long QBinomial(int n, int k, long q, int MOD)
        {
            if (k < 0 || k > n) return 0L;
            if (k == 0 || k == n) return 1L;
            // q == 1 is a singularity (0/0 in the product); by L'Hopital [n choose k]_1 = C(n,k).
            if (q % MOD == 1) return Binom(n, k, MOD);
            long num = 1L, den = 1L;
            for (int i = 0; i < k; i++)
            {
                long qi = ModPow(q, n - i, MOD);
                num = (num * ((qi - 1 + MOD) % MOD)) % MOD;
                long qj = ModPow(q, i + 1, MOD);
                den = (den * ((qj - 1 + MOD) % MOD)) % MOD;
            }
            return (num * ModPow(den, MOD - 2, MOD)) % MOD;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long GaussianBinomial(int n, int k, long q, int MOD) => QBinomial(n, k, q, MOD);

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Binom(int n, int k, int MOD)
        {
            if (k < 0 || k > n) return 0L;
            long num = Factorial(n, MOD);
            long den = (Factorial(k, MOD) * Factorial(n - k, MOD)) % MOD;
            return (num * ModPow(den, MOD - 2, MOD)) % MOD;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Factorial(int n, int MOD)
        {
            long r = 1L;
            for (int i = 2; i <= n; i++) r = (r * i) % MOD;
            return r;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long ModPow(long b, long e, long mod)
        {
            long r = 1L; b %= mod; if (b < 0L) b += mod;
            while (e > 0L) { if ((e & 1L) != 0L) r = (r * b) % mod; b = (b * b) % mod; e /= 2L; }
            return r;
        }
    }
}

namespace IAFahim.Algebra.Sequence
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class GeneratingFunction
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void EgfMultiply(long* a, long* b, int n, int MOD, long* result)
        {
            for (int i = 0; i < n; i++) result[i] = 0L;
            if (n <= 0) return;

            long mod = (long)MOD;

            // Precompute factorials and inverse factorials over [0, n-1] once.
            long* fact = stackalloc long[n];
            long* invfact = stackalloc long[n];
            fact[0] = 1L;
            for (int i = 1; i < n; i++) fact[i] = (fact[i - 1] * (long)i) % mod;
            invfact[n - 1] = Combinatorial.ModPow(fact[n - 1], mod - 2L, mod);
            for (int i = n - 1; i > 0; i--) invfact[i - 1] = (invfact[i] * (long)i) % mod;

            for (int i = 0; i < n; i++)
            for (int j = 0; j < n - i; j++)
            {
                // Binom(i+j, i) = (i+j)! / (i! * j!)  (mod prime MOD)
                long bin = ((fact[i + j] * invfact[i]) % mod * invfact[j]) % mod;
                result[i + j] = (result[i + j] + ((a[i] * b[j]) % mod) * bin) % mod;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void OgfMultiply(long* a, long* b, int n, int MOD, long* result)
        {
            for (int i = 0; i < n; i++) result[i] = 0L;
            for (int i = 0; i < n; i++)
            for (int j = 0; j < n - i; j++)
                result[i + j] = (result[i + j] + a[i] * b[j]) % (long)MOD;
        }

        // Returns the k-th coefficient g_k of the compositional inverse g of f,
        // where f(x) = f[1]*x + f[2]*x^2 + ... (f[0] = 0, f[1] invertible mod MOD).
        // Lagrange inversion: g_k = (1/k) * [x^{k-1}] (x/f(x))^k, computed modulo x^k.
        public static long LagrangeInversion(long* f, int n, int k, int MOD)
        {
            if (k <= 0) return 0L;

            long mod = (long)MOD;

            // phi(x) = f(x)/x, i.e. phi[i] = f[i+1]; we need phi[0..k-1] (f[1..k]).
            // h(x) = x/f(x) = 1/phi(x), the power-series inverse of phi, modulo x^k.
            long* h = stackalloc long[k];
            long invPhi0 = Combinatorial.ModPow(f[1], mod - 2L, mod);
            h[0] = invPhi0;
            for (int i = 1; i < k; i++)
            {
                long acc = 0L;
                // phi[j] = f[j+1]; sum_{j=1}^{i} phi[j] * h[i-j]
                for (int j = 1; j <= i; j++)
                    acc = (acc + f[j + 1] * h[i - j]) % mod;
                h[i] = (mod - (invPhi0 * acc) % mod) % mod;
            }

            // pw(x) = h(x)^k modulo x^k via binary exponentiation of truncated products.
            long* pw = stackalloc long[k];
            long* baseP = stackalloc long[k];
            long* tmp = stackalloc long[k];
            for (int i = 0; i < k; i++) { pw[i] = 0L; baseP[i] = h[i]; }
            pw[0] = 1L;

            int e = k;
            while (e > 0)
            {
                if ((e & 1) != 0)
                {
                    TruncMul(pw, baseP, tmp, k, mod);
                    for (int i = 0; i < k; i++) pw[i] = tmp[i];
                }
                e >>= 1;
                if (e > 0)
                {
                    TruncMul(baseP, baseP, tmp, k, mod);
                    for (int i = 0; i < k; i++) baseP[i] = tmp[i];
                }
            }

            long invK = Combinatorial.ModPow((long)k, mod - 2L, mod);
            return (pw[k - 1] * invK) % mod;
        }

        // dst = (a * b) modulo x^len, all coefficients reduced mod 'mod'. dst must differ from a and b.
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void TruncMul(long* a, long* b, long* dst, int len, long mod)
        {
            for (int i = 0; i < len; i++) dst[i] = 0L;
            for (int i = 0; i < len; i++)
            {
                long ai = a[i];
                if (ai == 0L) continue;
                for (int j = 0; j < len - i; j++)
                    dst[i + j] = (dst[i + j] + ai * b[j]) % mod;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long TreeCount(int n, int MOD)
        {
            if (n <= 1) return 1L;
            long result = Combinatorial.ModPow((long)n, (long)(n - 2), (long)MOD);
            return result;
        }
    }
}

namespace IAFahim.Algebra.Sequence
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Stirling
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void FirstRow(int n, int MOD, long* result)
        {
            for (int i = 0; i <= n; i++) result[i] = 0L;
            result[0] = 1L;
            for (int i = 1; i <= n; i++)
            {
                UpdateFirstRow(i, MOD, result);
                result[0] = 0L;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void UpdateFirstRow(int i, int MOD, long* result)
        {
            long factor = ((long)MOD - ((long)(i - 1) % (long)MOD)) % (long)MOD;
            for (int j = i; j >= 1; j--)
                result[j] = (result[j - 1] + factor * result[j]) % (long)MOD;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void SecondRow(int n, int MOD, long* result)
        {
            for (int i = 0; i <= n; i++) result[i] = 0L;
            result[0] = 1L;
            for (int i = 1; i <= n; i++)
            {
                UpdateSecondRow(i, MOD, result);
                result[0] = 0L;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void UpdateSecondRow(int i, int MOD, long* result)
        {
            for (int j = i; j >= 1; j--)
                result[j] = (result[j - 1] + (long)j * result[j]) % (long)MOD;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long First(int n, int k, int MOD)
        {
            long* row = stackalloc long[n + 1];
            FirstRow(n, MOD, row);
            return row[k];
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Second(int n, int k, int MOD)
        {
            long* row = stackalloc long[n + 1];
            SecondRow(n, MOD, row);
            return row[k];
        }
    }
}

namespace IAFahim.Algebra.Sequence
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class SubsetBell
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Run(long* a, int n, int MOD)
        {
            long* b = stackalloc long[n + 1]; b[0] = 1L;
            for (int i = 1; i <= n; i++) ComputeBellRow(i, MOD, b);

            long res = 0L; for (int i = 0; i < n; i++) res = (res + a[i] * b[i]) % (long)MOD;
            return res;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void ComputeBellRow(int i, int MOD, long* b)
        {
            b[i] = 0L; long binom = 1L;
            for (int k = 0; k < i; k++)
            {
                b[i] = (b[i] + binom * b[k]) % (long)MOD;
                binom = (binom * (long)(i - 1 - k)) % (long)MOD * Combinatorial.ModPow((long)(k + 1), (long)MOD - 2L, (long)MOD) % (long)MOD;
            }
        }
    }
}

namespace IAFahim.Collision.Gjk
{
    using System;
    using System.Runtime.CompilerServices;
    using Unity.Mathematics;

    public static unsafe class Gjk
    {
        private const float Epsilon = 1e-6f;
        private const int MaxIterations = 32;

        public delegate float3 SupportFunction(float3 direction);

        public static bool Intersect(SupportFunction supportA, SupportFunction supportB)
        {
            float3* simplexA = stackalloc float3[4];
            int count;
            return Intersect(supportA, supportB, simplexA, out count);
        }

        public static bool Intersect(SupportFunction supportA, SupportFunction supportB, float3* outSimplex, out int outCount)
        {
            outCount = 0;
            float3 dir = new float3(1.0f, 0.0f, 0.0f);
            float3* simplexA = stackalloc float3[4];
            int simplexCount = 0;

            float3 support = supportA(dir) - supportB(-dir);

            if (math.lengthsq(support) < Epsilon)
            {
                outSimplex[0] = support;
                outCount = 1;
                return true;
            }

            simplexA[0] = support;
            simplexCount = 1;

            dir = -support;

            for (int iter = 0; iter < MaxIterations; iter++)
            {
                support = supportA(dir) - supportB(-dir);

                if (math.dot(support, dir) < Epsilon)
                {
                    return false;
                }

                simplexA[simplexCount] = support;
                simplexCount++;

                if (DoSimplex(simplexA, ref simplexCount, ref dir))
                {
                    for (int i = 0; i < simplexCount; i++)
                    {
                        outSimplex[i] = simplexA[i];
                    }
                    outCount = simplexCount;
                    return true;
                }
            }

            return false;
        }

        public static float Distance(SupportFunction supportA, SupportFunction supportB)
        {
            float3 dir = new float3(1.0f, 0.0f, 0.0f);

            float3 sA = supportA(dir);
            float3 sB = supportB(-dir);
            float3 w0 = sA - sB;

            if (math.lengthsq(w0) < Epsilon)
            {
                return 0.0f;
            }

            float3* simplex = stackalloc float3[4];
            simplex[0] = w0;
            int count = 1;

            // closest is the current closest point on the simplex to the origin;
            // dir points from that closest point toward the origin.
            float3 closest = w0;
            float closestDistSq = math.lengthsq(w0);
            dir = -w0;

            for (int iter = 0; iter < MaxIterations; iter++)
            {
                sA = supportA(dir);
                sB = supportB(-dir);
                float3 w = sA - sB;

                // Progress test: the support point w lies on the supporting plane
                // of the CSO in direction dir. If it does not extend meaningfully
                // beyond the current closest point along dir, the closest feature
                // is optimal and the search has converged. Using the unnormalized
                // direction, the lack of progress is measured by comparing
                // dot(closest, closest) with dot(w, closest).
                float progress = closestDistSq - math.dot(w, closest);
                if (progress <= Epsilon * closestDistSq + Epsilon)
                {
                    break;
                }

                // Reject a support point already present in the simplex to avoid
                // a degenerate (zero-volume) addition and a stalled search.
                bool duplicate = false;
                for (int i = 0; i < count; i++)
                {
                    if (math.lengthsq(simplex[i] - w) < Epsilon)
                    {
                        duplicate = true;
                        break;
                    }
                }
                if (duplicate)
                {
                    break;
                }

                if (count < 4)
                {
                    simplex[count] = w;
                    count++;
                }

                closest = ComputeClosestPointToOrigin(simplex, ref count);
                closestDistSq = math.lengthsq(closest);

                if (closestDistSq < Epsilon)
                {
                    return 0.0f;
                }

                dir = -closest;
            }

            return math.sqrt(closestDistSq);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool DoSimplex(float3* simplex, ref int count, ref float3 dir)
        {
            bool intersected = false;
            if (count == 2)
            {
                intersected = LineCase(simplex, ref count, ref dir);
            }
            else if (count == 3)
            {
                intersected = TriangleCase(simplex, ref count, ref dir);
            }
            else if (count == 4)
            {
                intersected = TetrahedronCase(simplex, ref count, ref dir);
            }

            if (intersected)
            {
                return true;
            }

            if (math.lengthsq(dir) < Epsilon)
            {
                return true;
            }

            return false;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool LineCase(float3* s, ref int count, ref float3 dir)
        {
            float3 b = s[0], a = s[1];
            float3 ab = b - a;
            float3 ao = -a;

            if (math.dot(ab, ao) > 0.0f)
            {
                dir = math.cross(math.cross(ab, ao), ab);
            }
            else
            {
                s[0] = a;
                count = 1;
                dir = ao;
            }

            return false;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool TriangleCase(float3* s, ref int count, ref float3 dir)
        {
            float3 c = s[0], b = s[1], a = s[2];
            float3 ab = b - a;
            float3 ac = c - a;
            float3 ao = -a;
            float3 abc = math.cross(ab, ac);

            if (math.dot(math.cross(abc, ac), ao) > 0.0f)
            {
                if (math.dot(ac, ao) > 0.0f)
                {
                    s[0] = c;
                    s[1] = a;
                    count = 2;
                    dir = math.cross(math.cross(ac, ao), ac);
                }
                else
                {
                    s[0] = b;
                    s[1] = a;
                    count = 2;
                    return LineCase(s, ref count, ref dir);
                }
            }
            else
            {
                if (math.dot(math.cross(ab, abc), ao) > 0.0f)
                {
                    s[0] = b;
                    s[1] = a;
                    count = 2;
                    return LineCase(s, ref count, ref dir);
                }
                else
                {
                    if (math.dot(abc, ao) > 0.0f)
                    {
                        dir = abc;
                    }
                    else
                    {
                        float3 temp = s[0];
                        s[0] = s[1];
                        s[1] = temp;
                        dir = -abc;
                    }
                }
            }

            return false;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool TetrahedronCase(float3* s, ref int count, ref float3 dir)
        {
            float3 d = s[0], c = s[1], b = s[2], a = s[3];
            float3 ab = b - a;
            float3 ac = c - a;
            float3 ad = d - a;
            float3 ao = -a;

            float3 abc = math.cross(ab, ac);
            float3 acd = math.cross(ac, ad);
            float3 adb = math.cross(ad, ab);

            if (math.dot(abc, ao) > 0.0f)
            {
                s[0] = c;
                s[1] = b;
                s[2] = a;
                count = 3;
                return TriangleCase(s, ref count, ref dir);
            }

            if (math.dot(acd, ao) > 0.0f)
            {
                s[0] = d;
                s[1] = c;
                s[2] = a;
                count = 3;
                return TriangleCase(s, ref count, ref dir);
            }

            if (math.dot(adb, ao) > 0.0f)
            {
                s[0] = b;
                s[1] = d;
                s[2] = a;
                count = 3;
                return TriangleCase(s, ref count, ref dir);
            }

            return true;
        }

        // Returns the closest point on the current simplex to the origin and
        // reduces the simplex (in place, reordering vertices) to the minimal
        // sub-feature (vertex/edge/triangle) that contains the closest point.
        // For count == 4, if the origin is enclosed by the tetrahedron, the
        // closest point is the origin itself (returned as float3.zero).
        private static float3 ComputeClosestPointToOrigin(float3* simplex, ref int count)
        {
            if (count == 1)
            {
                return simplex[0];
            }

            if (count == 2)
            {
                return ClosestPointOnSegment(simplex, ref count);
            }

            if (count == 3)
            {
                return ClosestPointOnTriangle(simplex, ref count);
            }

            return ClosestPointOnTetrahedron(simplex, ref count);
        }

        // Closest point on segment [s0, s1] to the origin, reducing the simplex
        // to a single vertex when the closest feature is an endpoint.
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static float3 ClosestPointOnSegment(float3* simplex, ref int count)
        {
            float3 a = simplex[0];
            float3 b = simplex[1];
            float3 ab = b - a;

            float denom = math.dot(ab, ab);
            if (denom < Epsilon)
            {
                count = 1;
                return a;
            }

            float t = math.dot(-a, ab) / denom;

            if (t <= 0.0f)
            {
                count = 1;
                return a;
            }

            if (t >= 1.0f)
            {
                simplex[0] = b;
                count = 1;
                return b;
            }

            return a + t * ab;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool TryVertexA(float3 a, float d1, float d2, out float3 result, out int regionCount)
        {
            if (d1 <= 0.0f && d2 <= 0.0f) { result = a; regionCount = 1; return true; }
            result = default; regionCount = 0; return false;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool TryVertexB(float3* simplex, float3 b, float d3, float d4, out float3 result, out int regionCount)
        {
            if (d3 >= 0.0f && d4 <= d3) { simplex[0] = b; result = b; regionCount = 1; return true; }
            result = default; regionCount = 0; return false;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool TryEdgeAB(float3 a, float3 ab, float d1, float d3, float vc, out float3 result, out int regionCount)
        {
            if (vc <= 0.0f && d1 >= 0.0f && d3 <= 0.0f) { float t = d1 / (d1 - d3); result = a + t * ab; regionCount = 2; return true; }
            result = default; regionCount = 0; return false;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool TryVertexC(float3* simplex, float3 c, float d5, float d6, out float3 result, out int regionCount)
        {
            if (d6 >= 0.0f && d5 <= d6) { simplex[0] = c; result = c; regionCount = 1; return true; }
            result = default; regionCount = 0; return false;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool TryEdgeAC(float3* simplex, float3 a, float3 ac, float3 c, float d2, float d6, float vb, out float3 result, out int regionCount)
        {
            if (vb <= 0.0f && d2 >= 0.0f && d6 <= 0.0f) { float t = d2 / (d2 - d6); simplex[1] = c; result = a + t * ac; regionCount = 2; return true; }
            result = default; regionCount = 0; return false;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool TryEdgeBC(float3* simplex, float3 b, float3 c, float d3, float d4, float d5, float d6, float va, out float3 result, out int regionCount)
        {
            if (va <= 0.0f && (d4 - d3) >= 0.0f && (d5 - d6) >= 0.0f)
            {
                float t = (d4 - d3) / ((d4 - d3) + (d5 - d6));
                simplex[0] = b;
                simplex[1] = c;
                result = b + t * (c - b);
                regionCount = 2;
                return true;
            }
            result = default; regionCount = 0; return false;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static float3 ClosestPointOnTriangle(float3* simplex, ref int count)
        {
            float3 a = simplex[0];
            float3 b = simplex[1];
            float3 c = simplex[2];
            float3 ab = b - a;
            float3 ac = c - a;
            float3 ap = -a;
            float d1 = math.dot(ab, ap);
            float d2 = math.dot(ac, ap);
            float3 result;
            int regionCount;
            if (TryVertexA(a, d1, d2, out result, out regionCount)) { count = regionCount; return result; }
            float3 bp = -b;
            float d3 = math.dot(ab, bp);
            float d4 = math.dot(ac, bp);
            if (TryVertexB(simplex, b, d3, d4, out result, out regionCount)) { count = regionCount; return result; }
            float vc = d1 * d4 - d3 * d2;
            if (TryEdgeAB(a, ab, d1, d3, vc, out result, out regionCount)) { count = regionCount; return result; }
            float3 cp = -c;
            float d5 = math.dot(ab, cp);
            float d6 = math.dot(ac, cp);
            if (TryVertexC(simplex, c, d5, d6, out result, out regionCount)) { count = regionCount; return result; }
            float vb = d5 * d2 - d1 * d6;
            if (TryEdgeAC(simplex, a, ac, c, d2, d6, vb, out result, out regionCount)) { count = regionCount; return result; }
            float va = d3 * d6 - d5 * d4;
            if (TryEdgeBC(simplex, b, c, d3, d4, d5, d6, va, out result, out regionCount)) { count = regionCount; return result; }
            float denom = 1.0f / (va + vb + vc);
            float v = vb * denom;
            float w = vc * denom;
            count = 3;
            return a + ab * v + ac * w;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void ConsiderFace(bool degenerate, float3 a, float3 b, float3 c, float3 refVertex, int i0, int i1, int i2, ref float bestDistSq, ref int bestI0, ref int bestI1, ref int bestI2)
        {
            if (degenerate || PointOutsideFace(a, b, c, refVertex))
                EvaluateFace(a, b, c, i0, i1, i2, ref bestDistSq, ref bestI0, ref bestI1, ref bestI2);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static float3 ClosestPointOnTetrahedron(float3* simplex, ref int count)
        {
            float3 a = simplex[0];
            float3 b = simplex[1];
            float3 c = simplex[2];
            float3 d = simplex[3];
            float bestDistSq = float.MaxValue;
            int bestI0 = -1, bestI1 = -1, bestI2 = -1;
            float signedVolumeX6 = math.dot(b - a, math.cross(c - a, d - a));
            bool degenerate = math.abs(signedVolumeX6) < Epsilon;
            ConsiderFace(degenerate, a, b, c, d, 0, 1, 2, ref bestDistSq, ref bestI0, ref bestI1, ref bestI2);
            ConsiderFace(degenerate, a, c, d, b, 0, 2, 3, ref bestDistSq, ref bestI0, ref bestI1, ref bestI2);
            ConsiderFace(degenerate, a, d, b, c, 0, 3, 1, ref bestDistSq, ref bestI0, ref bestI1, ref bestI2);
            ConsiderFace(degenerate, b, d, c, a, 1, 3, 2, ref bestDistSq, ref bestI0, ref bestI1, ref bestI2);
            if (bestI0 < 0) { count = 4; return float3.zero; }
            float3 v0 = simplex[bestI0];
            float3 v1 = simplex[bestI1];
            float3 v2 = simplex[bestI2];
            simplex[0] = v0;
            simplex[1] = v1;
            simplex[2] = v2;
            count = 3;
            return ClosestPointOnTriangle(simplex, ref count);
        }

        // Evaluates the closest point on a single tetrahedron face (triangle) to
        // the origin and updates the running best. Uses a temporary local
        // simplex so the input array is not disturbed during evaluation.
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void EvaluateFace(
            float3 a, float3 b, float3 c,
            int i0, int i1, int i2,
            ref float bestDistSq,
            ref int bestI0, ref int bestI1, ref int bestI2)
        {
            float3* tri = stackalloc float3[3];
            tri[0] = a;
            tri[1] = b;
            tri[2] = c;
            int triCount = 3;
            float3 p = ClosestPointOnTriangle(tri, ref triCount);
            float distSq = math.dot(p, p);
            if (distSq < bestDistSq)
            {
                bestDistSq = distSq;
                bestI0 = i0;
                bestI1 = i1;
                bestI2 = i2;
            }
        }

        // True if the origin lies on the outward side of the plane through
        // (a, b, c), i.e. on the opposite side from the reference point d.
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool PointOutsideFace(float3 a, float3 b, float3 c, float3 d)
        {
            float3 normal = math.cross(b - a, c - a);
            float signOrigin = math.dot(normal, -a);
            float signRef = math.dot(normal, d - a);
            // Origin is outside when it sits strictly on the opposite side of
            // the plane from the reference vertex d.
            return signOrigin * signRef < 0.0f;
        }
    }
}

namespace IAFahim.Collision.Gjk
{
    using System;
    using System.Runtime.CompilerServices;
    using Unity.Mathematics;

    public static unsafe class Epa
    {
        private const float Epsilon = 1e-6f;

        private const int MaxIterations = 128;

        private const int MaxFaces = 256;

        private const int EdgesPerFace = 3;

        private const int TetrahedronVertexCount = 4;

        private const int RefineContinue = 0;

        private const int RefineConverged = 1;

        private const int RefineFailed = 2;

        private const float DirectionThresholdRatio = 0.9f;

        private const float PerturbationFactor = 0.1f;

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void TryAddHorizonEdge(int u, int v, int currentFace, int faceCount, bool* visible, int* faceA, int* faceB, int* faceC, int* horizonA, int* horizonB, ref int horizonCount)
        {
            if (IsHorizonEdge(u, v, currentFace, faceCount, visible, faceA, faceB, faceC))
            {
                horizonA[horizonCount] = u;
                horizonB[horizonCount] = v;
                horizonCount++;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void ExpandPolytope(float3 newSupport, float3* vertices, ref int vertexCount, float3* faceNormals, float* faceDistances, int* faceA, int* faceB, int* faceC, ref int faceCount)
        {
            int newIdx = vertexCount;
            vertices[vertexCount] = newSupport;
            vertexCount++;

            bool* visible = stackalloc bool[MaxFaces];
            for (int f = 0; f < faceCount; f++)
                visible[f] = math.dot(faceNormals[f], newSupport) - faceDistances[f] > Epsilon;

            int* horizonA = stackalloc int[MaxFaces * EdgesPerFace];
            int* horizonB = stackalloc int[MaxFaces * EdgesPerFace];
            int horizonCount = 0;

            for (int f = 0; f < faceCount; f++)
            {
                if (!visible[f]) continue;
                int aIdx = faceA[f], bIdx = faceB[f], cIdx = faceC[f];
                TryAddHorizonEdge(aIdx, bIdx, f, faceCount, visible, faceA, faceB, faceC, horizonA, horizonB, ref horizonCount);
                TryAddHorizonEdge(bIdx, cIdx, f, faceCount, visible, faceA, faceB, faceC, horizonA, horizonB, ref horizonCount);
                TryAddHorizonEdge(cIdx, aIdx, f, faceCount, visible, faceA, faceB, faceC, horizonA, horizonB, ref horizonCount);
            }

            for (int f = faceCount - 1; f >= 0; f--)
                if (visible[f]) RemoveFace(f, faceNormals, faceDistances, faceA, faceB, faceC, ref faceCount);

            for (int i = 0; i < horizonCount; i++)
                AddFace(vertices, horizonA[i], horizonB[i], newIdx, faceNormals, faceDistances, faceA, faceB, faceC, ref faceCount);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int RefineOnce(Gjk.SupportFunction supportA, Gjk.SupportFunction supportB, float3* vertices, ref int vertexCount, float3* faceNormals, float* faceDistances, int* faceA, int* faceB, int* faceC, ref int faceCount, out float3 outNormal, out float outDepth)
        {
            outNormal = float3.zero;
            outDepth = 0.0f;
            int closestFace = FindClosestFace(faceDistances, faceCount);
            if (closestFace < 0) return RefineFailed;
            float minDist = faceDistances[closestFace];
            float3 faceNormal = faceNormals[closestFace];
            float3 newSupport = supportA(faceNormal) - supportB(-faceNormal);
            float supDist = math.dot(newSupport, faceNormal);
            if (supDist - minDist < Epsilon)
            {
                outNormal = faceNormal;
                outDepth = minDist;
                return RefineConverged;
            }
            ExpandPolytope(newSupport, vertices, ref vertexCount, faceNormals, faceDistances, faceA, faceB, faceC, ref faceCount);
            return RefineContinue;
        }

        public static float PenetrationDepth(Gjk.SupportFunction supportA, Gjk.SupportFunction supportB,
            float3* initialSimplex, int simplexCount, out float3 normal, out float depth)
        {
            normal = float3.zero;
            depth = 0.0f;

            float3* vertices = stackalloc float3[MaxIterations + TetrahedronVertexCount];
            int vertexCount = simplexCount;
            for (int i = 0; i < simplexCount; i++) vertices[i] = initialSimplex[i];

            if (vertexCount < TetrahedronVertexCount)
            {
                ExpandSimplex(supportA, supportB, vertices, ref vertexCount);
            }

            float3* faceNormals = stackalloc float3[MaxFaces];
            float* faceDistances = stackalloc float[MaxFaces];
            int* faceA = stackalloc int[MaxFaces];
            int* faceB = stackalloc int[MaxFaces];
            int* faceC = stackalloc int[MaxFaces];
            int faceCount = 0;

            AddFace(vertices, 0, 1, 2, faceNormals, faceDistances, faceA, faceB, faceC, ref faceCount);
            AddFace(vertices, 0, 3, 1, faceNormals, faceDistances, faceA, faceB, faceC, ref faceCount);
            AddFace(vertices, 0, 2, 3, faceNormals, faceDistances, faceA, faceB, faceC, ref faceCount);
            AddFace(vertices, 1, 3, 2, faceNormals, faceDistances, faceA, faceB, faceC, ref faceCount);

            for (int iter = 0; iter < MaxIterations; iter++)
            {
                int status = RefineOnce(supportA, supportB, vertices, ref vertexCount, faceNormals, faceDistances, faceA, faceB, faceC, ref faceCount, out float3 iterNormal, out float iterDepth);
                if (status == RefineFailed) return 0.0f;
                if (status == RefineConverged) { normal = iterNormal; depth = iterDepth; return depth; }
            }

            return 0.0f;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool IsHorizonEdge(int u, int v, int currentFace, int faceCount, bool* visible, int* fa, int* fb, int* fc)
        {
            for (int i = 0; i < faceCount; i++)
            {
                if (i == currentFace) continue;
                int a = fa[i];
                int b = fb[i];
                int c = fc[i];
                bool containsU = a == u || b == u || c == u;
                bool containsV = a == v || b == v || c == v;
                if (containsU && containsV) return !visible[i];
            }
            return true;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void AddFace(float3* vertices, int a, int b, int c,
            float3* normals, float* distances, int* fa, int* fb, int* fc, ref int faceCount)
        {
            if (faceCount >= MaxFaces) return;
            float3 ab = vertices[b] - vertices[a];
            float3 ac = vertices[c] - vertices[a];
            float3 n = math.cross(ab, ac);
            float len = math.length(n);
            if (len < Epsilon) return;
            n = n / len;
            float d = math.dot(n, vertices[a]);
            if (d < 0.0f) { n = -n; d = -d; }
            int idx = faceCount;
            normals[idx] = n;
            distances[idx] = d;
            fa[idx] = a;
            fb[idx] = b;
            fc[idx] = c;
            faceCount++;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int FindClosestFace(float* distances, int faceCount)
        {
            if (faceCount == 0) return -1;
            int closest = 0;
            float minDist = distances[0];
            for (int i = 1; i < faceCount; i++)
                if (distances[i] < minDist) { minDist = distances[i]; closest = i; }
            return closest;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void RemoveFace(int idx, float3* normals, float* distances,
            int* fa, int* fb, int* fc, ref int faceCount)
        {
            int last = faceCount - 1;
            if (idx < last)
            {
                normals[idx] = normals[last];
                distances[idx] = distances[last];
                fa[idx] = fa[last];
                fb[idx] = fb[last];
                fc[idx] = fc[last];
            }
            faceCount--;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void ExpandSimplex(Gjk.SupportFunction supportA, Gjk.SupportFunction supportB,
            float3* vertices, ref int vertexCount)
        {
            if (vertexCount == 1)
            {
                float3 a = vertices[0];
                float3 dir = math.lengthsq(a) < Epsilon ? new float3(1.0f, 0.0f, 0.0f) : -a;
                vertices[1] = supportA(dir) - supportB(-dir);
                vertexCount = 2;
            }

            if (vertexCount == 2)
            {
                float3 a = vertices[0], b = vertices[1];
                float3 ab = b - a;
                float3 dir = new float3(1.0f, 0.0f, 0.0f);
                if (math.abs(ab.x) > DirectionThresholdRatio * math.length(ab))
                {
                    dir = new float3(0.0f, 1.0f, 0.0f);
                }
                dir = math.cross(ab, dir) + ab * PerturbationFactor;
                vertices[2] = supportA(dir) - supportB(-dir);
                vertexCount = 3;
            }

            if (vertexCount == 3)
            {
                float3 a = vertices[0], b = vertices[1], c = vertices[2];
                float3 ab = b - a;
                float3 ac = c - a;
                float3 dir = math.cross(ab, ac);
                if (math.lengthsq(dir) < Epsilon)
                {
                    dir = new float3(0.0f, 0.0f, 1.0f);
                }
                dir = dir + (ab + ac) * PerturbationFactor;
                vertices[3] = supportA(dir) - supportB(-dir);
                vertexCount = 4;
            }
        }
    }
}

namespace IAFahim.Collision.Gjk
{
    using System;
    using System.Runtime.CompilerServices;
    using Unity.Mathematics;

    public static unsafe class MinkowskiDifference
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float3 SphereSupport(float3 direction, float3 center, float radius)
        {
            float len = math.length(direction);
            if (len < 1e-6f)
            {
                return center;
            }

            return center + (direction / len) * radius;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float3 BoxSupport(float3 direction, float3 center, float3 halfExtents)
        {
            float3 n = math.normalizesafe(direction);
            return center + halfExtents * math.sign(n);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float3 CapsuleSupport(float3 direction, float3 a, float3 b, float radius)
        {
            float3 ba = b - a;
            float t = math.dot(direction, ba);
            float lenSq = math.dot(ba, ba);

            if (lenSq < 1e-6f)
            {
                return SphereSupport(direction, a, radius);
            }

            float param = math.clamp(t / lenSq, 0.0f, 1.0f);
            float3 closest = a + ba * param;
            return SphereSupport(direction, closest, radius);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float3 ConvexHullSupport(float3 direction, float3* points, int count)
        {
            if (count <= 0)
            {
                return float3.zero;
            }

            float3 best = points[0];
            float maxDot = math.dot(direction, best);

            for (int i = 1; i < count; i++)
            {
                float d = math.dot(direction, points[i]);
                if (d > maxDot)
                {
                    maxDot = d;
                    best = points[i];
                }
            }

            return best;
        }
    }
}

