    public static unsafe class BranchAndBound
    {
        public static long Run(int n, long* weight, long* value, long capacity, long* bestValue, int* bestSet)
        {
            *bestValue = 0;
            long curW = 0, curV = 0;
            int* curSet = stackalloc int[n];
            int* visited = stackalloc int[n];
            for (int i = 0; i < n; i++) visited[i] = 0;
            BranchRec(n, 0, weight, value, capacity, &curW, &curV, bestValue, curSet, visited);
            for (int i = 0; i < n; i++) bestSet[i] = visited[i];
            return *bestValue;
        }

        private static void BranchRec(int n, int idx, long* weight, long* value, long capacity, long* curW, long* curV, long* bestV, int* curSet, int* bestSet)
        {
            if (idx == n)
            {
                UpdateBestSolution(n, curV, bestV, curSet, bestSet);
                return;
            }
            if (*curW + weight[idx] <= capacity)
            {
                IncludeItem(n, idx, weight, value, capacity, curW, curV, bestV, curSet, bestSet);
            }
            if (CanPrune(n, idx, *curV, *bestV, value)) return;
            ExcludeItem(n, idx, weight, value, capacity, curW, curV, bestV, curSet, bestSet);
        }

        private static void UpdateBestSolution(int n, long* curV, long* bestV, int* curSet, int* bestSet)
        {
            if (*curV > *bestV)
            {
                *bestV = *curV;
                for (int i = 0; i < n; i++) bestSet[i] = curSet[i];
            }
        }

        private static void IncludeItem(int n, int idx, long* weight, long* value, long capacity, long* curW, long* curV, long* bestV, int* curSet, int* bestSet)
        {
            curSet[idx] = 1;
            *curW += weight[idx];
            *curV += value[idx];
            BranchRec(n, idx + 1, weight, value, capacity, curW, curV, bestV, curSet, bestSet);
            *curW -= weight[idx];
            *curV -= value[idx];
        }

        private static void ExcludeItem(int n, int idx, long* weight, long* value, long capacity, long* curW, long* curV, long* bestV, int* curSet, int* bestSet)
        {
            curSet[idx] = 0;
            BranchRec(n, idx + 1, weight, value, capacity, curW, curV, bestV, curSet, bestSet);
        }

        private static bool CanPrune(int n, int idx, long curV, long bestV, long* value)
        {
            long remaining = 0;
            for (int i = idx; i < n; i++) remaining += value[i];
            return curV + remaining <= bestV;
        }
    }

    public static unsafe class Knapsack01
    {
        public static long Run(int n, long capacity, long* weight, long* value, long* dp)
        {
            for (int i = 0; i <= n; i++)
                UpdateKnapsack01Row(i, n, capacity, weight, value, dp);
            return dp[n * (capacity + 1) + (int)capacity];
        }

        private static void UpdateKnapsack01Row(int i, int n, long capacity, long* weight, long* value, long* dp)
        {
            int cols = (int)capacity + 1;
            for (long w = 0; w <= capacity; w++)
            {
                if (i == 0 || w == 0) dp[i * cols + (int)w] = 0;
                else if (weight[i - 1] <= w)
                {
                    long include = value[i - 1] + dp[(i - 1) * cols + (int)(w - weight[i - 1])];
                    long exclude = dp[(i - 1) * cols + (int)w];
                    dp[i * cols + (int)w] = include > exclude ? include : exclude;
                }
                else dp[i * cols + (int)w] = dp[(i - 1) * cols + (int)w];
            }
        }

        public static long RunSpaceOptimized(int n, long capacity, long* weight, long* value, long* dp)
        {
            for (int i = 0; i <= capacity; i++) dp[i] = 0;
            for (int i = 0; i < n; i++)
                UpdateKnapsack01SpaceOptimized(capacity, weight[i], value[i], dp);
            return dp[capacity];
        }

        private static void UpdateKnapsack01SpaceOptimized(long capacity, long weight, long value, long* dp)
        {
            for (long w = capacity; w >= weight; w--)
            {
                long val = dp[w - (int)weight] + value;
                if (val > dp[w]) dp[w] = val;
            }
        }
    }

    public static unsafe class KnapsackUnbounded
    {
        public static long Run(int n, long capacity, long* weight, long* value, long* dp)
        {
            for (int i = 0; i <= capacity; i++) dp[i] = 0;
            for (long w = 0; w <= capacity; w++)
                UpdateKnapsackUnbounded(n, w, weight, value, dp);
            return dp[capacity];
        }

        private static void UpdateKnapsackUnbounded(int n, long w, long* weight, long* value, long* dp)
        {
            for (int i = 0; i < n; i++)
            {
                if (weight[i] <= w)
                {
                    long val = dp[w - (int)weight[i]] + value[i];
                    if (val > dp[w]) dp[w] = val;
                }
            }
        }
    }

    public static unsafe class KnapsackBounded
    {
        public static long Run(int n, long capacity, long* weight, long* value, int* count, long* dp)
        {
            for (int i = 0; i <= capacity; i++) dp[i] = 0;
            for (int i = 0; i < n; i++)
                UpdateKnapsackBoundedRow(capacity, weight[i], value[i], count[i], dp);
            return dp[capacity];
        }

        private static void UpdateKnapsackBoundedRow(long capacity, long weight, long value, int count, long* dp)
        {
            for (long w = capacity; w >= 0; w--)
                for (int k = 1; k <= count && k * weight <= w; k++)
                {
                    long val = dp[w - (int)(k * weight)] + k * value;
                    if (val > dp[w]) dp[w] = val;
                }
        }
    }

    public static unsafe class SubsetSum
    {
        public static bool Run(int n, long target, long* arr, bool* dp)
        {
            for (int i = 0; i <= target; i++) dp[i] = false;
            dp[0] = true;
            for (int i = 0; i < n; i++)
                UpdateSubsetSum(target, arr[i], dp);
            return dp[target];
        }

        private static void UpdateSubsetSum(long target, long val, bool* dp)
        {
            for (long s = target; s >= val; s--)
                if (dp[s - (int)val]) dp[s] = true;
        }
    }

    public static unsafe class BitsetSubsetSum
    {
        public static long Run(int n, long target, ulong* bitset, long* arr)
        {
            int bitLen = (int)(target >> 6) + 1;
            for (int i = 0; i < bitLen; i++) bitset[i] = 0;
            bitset[0] = 1UL;
            for (int i = 0; i < n; i++)
                ApplyBitsetShift(bitLen, target, bitset, arr[i]);
            return (bitset[(int)(target >> 6)] & (1UL << (int)(target & 63))) != 0 ? 1 : 0;
        }

        private static void ApplyBitsetShift(int bitLen, long target, ulong* bitset, long val)
        {
            int shift = (int)val;
            if (shift < 0 || shift > target) return;
            int wordShift = shift >> 6;
            int bitShift = shift & 63;
            for (int b = bitLen - 1; b >= 0; b--)
            {
                ulong lo = 0, hi = 0;
                if (b - wordShift >= 0) lo = bitset[b - wordShift] << bitShift;
                if (bitShift > 0 && b - wordShift - 1 >= 0) hi = bitset[b - wordShift - 1] >> (64 - bitShift);
                bitset[b] |= lo | hi;
            }
        }
    }

    public static unsafe class DivideConquerDp
    {
        public static void Optimize(int n, int k, long* dp, long* newDp, long* cost)
        {
            for (int i = 0; i <= n; i++) newDp[i] = long.MaxValue;
            int* opt = stackalloc int[n + 1];
            DcRec(1, n, 1, k, dp, newDp, opt, cost);
        }

        private static void DcRec(int l, int r, int optL, int optR, long* dp, long* newDp, int* opt, long* cost)
        {
            if (l > r) return;
            int mid = (l + r) >> 1;
            int bestOpt = -1;
            long bestVal = long.MaxValue;
            for (int k = optL; k <= Math.Min(mid, optR); k++)
            {
                long val = dp[k - 1] + cost[k + mid];
                if (val < bestVal) { bestVal = val; bestOpt = k; }
            }
            newDp[mid] = bestVal;
            opt[mid] = bestOpt;
            DcRec(l, mid - 1, optL, bestOpt, dp, newDp, opt, cost);
            DcRec(mid + 1, r, bestOpt, optR, dp, newDp, opt, cost);
        }
    }

    public static unsafe class KnuthOptimization
    {
        public static void Optimize(int n, long* dp, long* newDp, long* cost, int* opt)
        {
            for (int i = 1; i <= n; i++)
            {
                newDp[i] = long.MaxValue;
                for (int j = 1; j <= i; j++)
                {
                    long val = dp[j - 1] + cost[j + i];
                    if (val < newDp[i]) { newDp[i] = val; opt[i] = j; }
                }
            }
        }
    }

    public static unsafe class ConvexHullTrickAdd
    {
        // Lower envelope, MIN query. Lines must be added with strictly decreasing slopes.
        public static void AddLine(long m, long b, long* ms, long* bs, int* sz)
        {
            while (*sz >= 2 && Redundant(ms, bs, *sz - 2, *sz - 1, m, b)) (*sz)--;
            ms[*sz] = m; bs[*sz] = b; (*sz)++;
        }

        // Middle line b is redundant when intersection(a,b) >= intersection(b,new).
        // Denominators (ms[a]-ms[b]) and (ms[b]-m) are positive under decreasing-slope contract.
        private static bool Redundant(long* ms, long* bs, int a, int b, long m2, long b2)
            => (bs[b] - bs[a]) * (ms[b] - m2) >= (b2 - bs[b]) * (ms[a] - ms[b]);

        public static long Query(long x, long* ms, long* bs, int sz)
        {
            if (sz <= 0) return long.MaxValue;
            int lo = 0, hi = sz - 1;
            while (lo < hi)
            {
                int mid = (lo + hi) >> 1;
                long num = bs[mid + 1] - bs[mid];
                long den = ms[mid] - ms[mid + 1];
                if (x * den <= num) hi = mid;
                else lo = mid + 1;
            }
            return Eval(ms, bs, lo, x);
        }

        private static long Eval(long* ms, long* bs, int idx, long x) => ms[idx] * x + bs[idx];
    }

    public static unsafe class LiChaoAddLine
    {
        public static void AddLine(long m, long b, int node, long l, long r, long* ms, long* bs, bool* has)
        {
            if (!has[node]) { ms[node] = m; bs[node] = b; has[node] = true; return; }
            long mid = (l + r) >> 1;
            if (ms[node] * mid + bs[node] > m * mid + b)
            {
                Swap(ref ms[node], ref m); Swap(ref bs[node], ref b);
            }
            if (l == r) return;
            if (ms[node] * l + bs[node] > m * l + b) AddLine(m, b, node * 2, l, mid, ms, bs, has);
            else AddLine(m, b, node * 2 + 1, mid + 1, r, ms, bs, has);
        }

        private static void Swap(ref long a, ref long b) { long t = a; a = b; b = t; }

        public static long Query(int node, long l, long r, long x, long* ms, long* bs, bool* has)
        {
            if (!has[node]) return long.MaxValue;
            long res = ms[node] * x + bs[node];
            if (l == r) return res;
            long mid = (l + r) >> 1;
            if (x <= mid) return Math.Min(res, Query(node * 2, l, mid, x, ms, bs, has));
            return Math.Min(res, Query(node * 2 + 1, mid + 1, r, x, ms, bs, has));
        }
    }

    public static unsafe class Smawk
    {
        // Column-wise running minimum: dp[j] = min over rows i of mat[i*m+j].
        public static long Run(int n, int m, long* mat, long* dp)
        {
            for (int j = 0; j < m; j++) dp[j] = mat[0 * m + j];
            for (int i = 1; i < n; i++)
            {
                long* row = mat + (long)i * m;
                for (int j = 0; j < m; j++)
                    if (row[j] < dp[j]) dp[j] = row[j];
            }
            long ans = long.MaxValue;
            for (int j = 0; j < m; j++) if (dp[j] < ans) ans = dp[j];
            return ans;
        }
    }

    public static unsafe class AlienDp
    {
        public static long Run(int n, long k, long* arr, Func<long, long, long> dist)
        {
            long lo = 0, hi = CalculateMaxDist(n, arr);
            while (lo < hi)
            {
                long mid = (lo + hi) >> 1;
                if (CountGroups(n, mid, arr, dist) <= k) hi = mid;
                else lo = mid + 1;
            }
            return lo;
        }

        private static long CalculateMaxDist(int n, long* arr)
        {
            long hi = 0;
            for (int i = 0; i < n; i++) hi += Math.Abs(arr[i]);
            return hi;
        }

        private static int CountGroups(int n, long mid, long* arr, Func<long, long, long> dist)
        {
            int groups = 1;
            long cur = 0;
            for (int i = 0; i < n; i++)
            {
                long d = dist(cur, arr[i]);
                if (cur + d > mid) { groups++; cur = d; }
                else cur += d;
            }
            return groups;
        }
    }

    public static unsafe class SubsetDp
    {
        public static void Run(int n, long* dp, long* newDp)
        {
            for (int i = 0; i < n; i++)
                UpdateSubsetDp(n, i, dp, newDp);
        }

        private static void UpdateSubsetDp(int n, int i, long* dp, long* newDp)
        {
            for (int mask = 0; mask < (1 << n); mask++)
                if ((mask & (1 << i)) != 0)
                    newDp[mask] += dp[mask ^ (1 << i)];
        }
    }

    public static unsafe class SosDp
    {
        public static void Run(int n, long* f)
        {
            for (int i = 0; i < n; i++)
                UpdateSosDp(n, i, f);
        }

        private static void UpdateSosDp(int n, int i, long* f)
        {
            for (int mask = 0; mask < (1 << n); mask++)
                if ((mask & (1 << i)) != 0)
                    f[mask] += f[mask ^ (1 << i)];
        }
    }

    public static unsafe class IntervalDp
    {
        public static long Run(int n, long* dp, long* cost)
        {
            for (int len = 1; len <= n; len++)
                for (int i = 0; i + len <= n; i++)
                {
                    int j = i + len - 1;
                    dp[i * n + j] = FindBestIntervalSplit(i, j, n, dp, cost);
                }
            return dp[0 * n + (n - 1)];
        }

        private static long FindBestIntervalSplit(int i, int j, int n, long* dp, long* cost)
        {
            long best = long.MaxValue;
            for (int k = i; k <= j; k++)
            {
                long val = (i < k ? dp[i * n + k - 1] : 0) + (k < j ? dp[(k + 1) * n + j] : 0) + cost[i * n + j];
                if (val < best) best = val;
            }
            return best;
        }
    }

    public static unsafe class MinPlusConvolution
    {
        public static void Run(int n, long* a, long* b, long* c)
        {
            for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                c[i * n + j] = FindMinPlusVal(i, j, n, a, b);
        }

        private static long FindMinPlusVal(int i, int j, int n, long* a, long* b)
        {
            long best = long.MaxValue;
            for (int k = 0; k < n; k++)
            {
                long val = a[i * n + k] + b[k * n + j];
                if (val < best) best = val;
            }
            return best;
        }
    }

    public static unsafe class MaxPlusConvolution
    {
        public static void Run(int n, long* a, long* b, long* c)
        {
            for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                c[i * n + j] = FindMaxPlusVal(i, j, n, a, b);
        }

        private static long FindMaxPlusVal(int i, int j, int n, long* a, long* b)
        {
            long best = long.MinValue;
            for (int k = 0; k < n; k++)
            {
                long val = a[i * n + k] + b[k * n + j];
                if (val > best) best = val;
            }
            return best;
        }
    }
}

namespace IAFahim.DP.General
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class ProfileDp
    {
        public static long Run(int m, int n, int* a, long* dp, long* tmp)
        {
            InitializeDp(m, dp);
            for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
            {
                UpdateProfileDpMasks(m, j, a + i * m, dp, tmp);
                long* swap = dp; dp = tmp; tmp = swap;
            }
            return dp[0];
        }

        private static void InitializeDp(int m, long* dp)
        {
            int maskCount = 1 << m;
            for (int i = 0; i < maskCount; i++) dp[i] = long.MinValue;
            dp[0] = 0;
        }

        private static void UpdateProfileDpMasks(int m, int j, int* rowA, long* dp, long* tmp)
        {
            int bit = 1 << j;
            int maskCount = 1 << m;
            long addV = rowA[j];
            for (int mask = 0; mask < maskCount; mask++) tmp[mask] = dp[mask];
            for (int mask = bit; mask < maskCount; mask = (mask + 1) | bit)
            {
                long cur = dp[mask];
                if (cur != long.MinValue)
                {
                    int nmask = mask ^ bit;
                    long cand = cur + addV;
                    if (cand > tmp[nmask]) tmp[nmask] = cand;
                }
            }
        }
    }

    public static unsafe class BrokenProfileDp
    {
        public static long Run(int m, int n, int* a, long* dp, long* tmp, int* state)
        {
            InitializeDp(m, dp);
            for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
            {
                UpdateBrokenProfileDpMasks(m, j, a + i * m, dp, tmp);
                long* swap = dp; dp = tmp; tmp = swap;
            }
            return dp[0];
        }

        private static void InitializeDp(int m, long* dp)
        {
            int maskCount = 1 << m;
            for (int i = 0; i < maskCount; i++) dp[i] = long.MinValue;
            dp[0] = 0;
        }

        private static void UpdateBrokenProfileDpMasks(int m, int j, int* rowA, long* dp, long* tmp)
        {
            int bit = 1 << j;
            int maskCount = 1 << m;
            long addV = rowA[j];
            for (int mask = 0; mask < maskCount; mask++) tmp[mask] = dp[mask];
            for (int mask = bit; mask < maskCount; mask = (mask + 1) | bit)
            {
                long cur = dp[mask];
                if (cur != long.MinValue)
                {
                    int nmask = mask ^ bit;
                    long cand = cur + addV;
                    if (cand > tmp[nmask]) tmp[nmask] = cand;
                }
            }
        }
    }

    public static unsafe class TreeKnapsack
    {
        public static void Run(int u, int p, int* head, int* to, int* next, int* w, long* v, long* dp, long* tmp, int cap)
        {
            dp[u * cap] = 0;
            int size = 1;
            for (int e = head[u]; e != 0; e = next[e])
            {
                int vNode = to[e];
                if (vNode == p) continue;
                int subSize = 0;
                Run(vNode, u, head, to, next, w, v, dp, tmp, cap);
                ProcessTreeKnapsackChild(u, vNode, v[vNode], w[vNode], size, subSize, dp, cap);
                size += subSize;
            }
        }

        private static void ProcessTreeKnapsackChild(int u, int vNode, long valV, int weightV, int size, int subSize, long* dp, int cap)
        {
            long val2 = dp[vNode * cap + subSize] + valV;
            long* dpU = dp + u * cap;
            int start = Math.Min(size, cap) - 1;
            int limit = cap - weightV - 1;
            if (limit < start) start = limit;
            for (int i = start; i >= 0; i--)
            {
                long* slot = dpU + i + weightV;
                if (val2 > *slot) *slot = val2;
            }
        }
    }

    public static unsafe class IntervalDp
    {
        public static long Run(int n, int* a, long* dp, long* tmp)
        {
            for (int i = 0; i < n; i++) dp[i * n + i] = 0;
            for (int len = 2; len <= n; len++)
            {
                for (int i = 0; i + len <= n; i++)
                {
                    int j = i + len - 1;
                    dp[i * n + j] = FindBestIntervalSplit(i, j, n, dp);
                }
            }
            return dp[0 * n + (n - 1)];
        }

        private static long FindBestIntervalSplit(int i, int j, int n, long* dp)
        {
            long best = long.MaxValue;
            long* rowI = dp + i * n;
            long* rowK = dp + (i + 1) * n + j;
            for (int k = i; k < j; k++)
            {
                long d1 = rowI[k];
                long d2 = *rowK;
                if (d1 != long.MaxValue && d2 != long.MaxValue)
                {
                    long cand = d1 + d2 + 1;
                    if (cand < best) best = cand;
                }
                rowK += n;
            }
            return best;
        }
    }

    public static unsafe class MinPlusConvolution
    {
        public static void Run(int n, int m, long* a, long* b, long* c, long INF)
        {
            for (int i = 0; i < n + m; i++) c[i] = INF;
            for (int i = 0; i < n; i++)
            {
                long ai = a[i];
                if (ai == INF) continue;
                long* cBase = c + i;
                for (int j = 0; j < m; j++)
                {
                    long bj = b[j];
                    if (bj != INF)
                    {
                        long val = ai + bj;
                        if (val < cBase[j]) cBase[j] = val;
                    }
                }
            }
        }
    }

    public static unsafe class QuadrangleInequalityDp
    {
        public static long Run(int n, int m, long* dp, long* tmp, int* opt)
        {
            for (int i = 0; i < n; i++) { dp[i * n + i] = 0; opt[i] = i; }
            for (int len = 2; len <= m; len++)
            {
                for (int i = 0; i + len <= n; i++)
                {
                    int j = i + len - 1;
                    dp[i * n + j] = FindBestQuadrangleSplit(i, j, n, dp, opt);
                }
            }
            return dp[0 * n + (m - 1)];
        }

        private static long FindBestQuadrangleSplit(int i, int j, int n, long* dp, int* opt)
        {
            long best = long.MaxValue;
            int bestK = i;
            int start = opt[i], end = (i + 1 < n) ? opt[i + 1] : j - 1;
            if (end > j - 1) end = j - 1;
            long* rowI = dp + i * n;
            long* rowK = dp + (start + 1) * n + j;
            for (int k = start; k <= end; k++)
            {
                long d1 = rowI[k], d2 = *rowK;
                if (d1 != long.MaxValue && d2 != long.MaxValue)
                {
                    long val = d1 + d2 + 1;
                    if (val < best) { best = val; bestK = k; }
                }
                rowK += n;
            }
            opt[i] = bestK;
            return best;
        }
    }
}

namespace IAFahim.DP.Knapsack
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Knapsack01
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Run(int n, long cap, long* w, long* v, long* dp)
        {
            InitializeDp(cap, dp);
            for (int i = 0; i < n; i++)
                UpdateKnapsack01(cap, w[i], v[i], dp);
            return dp[(int)cap];
        }

        private static void InitializeDp(long cap, long* dp)
        {
            for (long i = 0; i <= cap; i++) dp[i] = 0;
        }

        private static void UpdateKnapsack01(long cap, long weight, long value, long* dp)
        {
            for (long c = cap; c >= weight; c--)
            {
                long val = dp[(int)(c - weight)] + value;
                if (val > dp[(int)c]) dp[(int)c] = val;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long RunSpaceEfficient(int n, long cap, long* w, long* v, long* dp) => Run(n, cap, w, v, dp);
    }

    public static unsafe class KnapsackUnbounded
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Run(int n, long cap, long* w, long* v, long* dp)
        {
            for (long i = 0; i <= cap; i++) dp[i] = 0;
            for (long c = 1; c <= cap; c++)
                UpdateKnapsackUnbounded(c, n, w, v, dp);
            return dp[(int)cap];
        }

        private static void UpdateKnapsackUnbounded(long c, int n, long* w, long* v, long* dp)
        {
            for (int i = 0; i < n; i++)
            {
                if (w[i] <= c)
                {
                    long val = dp[(int)(c - w[i])] + v[i];
                    if (val > dp[(int)c]) dp[(int)c] = val;
                }
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long RunSpaceEfficient(int n, long cap, long* w, long* v, long* dp) => Run(n, cap, w, v, dp);
    }

    public static unsafe class KnapsackBounded
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Run(int n, long cap, long* w, long* v, long* cnt, long* dp)
        {
            for (long i = 0; i <= cap; i++) dp[i] = 0;
            for (int i = 0; i < n; i++)
                ProcessBoundedItem(cap, w[i], v[i], cnt[i], dp);
            return dp[(int)cap];
        }

        private static void ProcessBoundedItem(long cap, long weight, long value, long count, long* dp)
        {
            if (count == 1)
            {
                UpdateKnapsack01(cap, weight, value, dp);
            }
            else if (count > 1)
            {
                long maxUse = Math.Min(count, cap / weight);
                for (long c = cap; c >= 0; c--)
                    UpdateBoundedCap(c, maxUse, weight, value, dp);
            }
        }

        private static void UpdateKnapsack01(long cap, long weight, long value, long* dp)
        {
            for (long c = cap; c >= weight; c--)
            {
                long val = dp[(int)(c - weight)] + value;
                if (val > dp[(int)c]) dp[(int)c] = val;
            }
        }

        private static void UpdateBoundedCap(long c, long maxUse, long weight, long value, long* dp)
        {
            for (long k = 1; k <= maxUse && c >= k * weight; k++)
            {
                long val = dp[(int)(c - k * weight)] + k * value;
                if (val > dp[(int)c]) dp[(int)c] = val;
            }
        }
    }

    public static unsafe class SubsetSum
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool Run(int n, long target, long* a, bool* dp)
        {
            for (long i = 0; i <= target; i++) dp[i] = false;
            dp[0] = true;
            for (int i = 0; i < n; i++)
                UpdateSubsetSum(target, a[i], dp);
            return dp[(int)target];
        }

        private static void UpdateSubsetSum(long target, long val, bool* dp)
        {
            for (long s = target; s >= val; s--)
                if (dp[(int)(s - val)]) dp[(int)s] = true;
        }
    }

    public static unsafe class BitsetSubsetSum
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Run(int n, long target, long* a, long* bits)
        {
            int size = (int)((target >> 6) + 1);
            for (int i = 0; i < size; i++) bits[i] = 0;
            bits[0] = 1L;
            for (int i = 0; i < n; i++)
                BitsetShiftOr(size, a[i], bits);

            int targetIdx = (int)(target >> 6);
            int targetBit = (int)(target & 63);
            return (targetIdx < size && (bits[targetIdx] & (1L << targetBit)) != 0) ? 1 : 0;
        }

        private static void BitsetShiftOr(int size, long val, long* bits)
        {
            int shift = (int)(val & 63);
            int offset = (int)(val >> 6);
            if (shift == 0)
            {
                for (int j = size - 1; j >= offset; j--)
                    bits[j] |= bits[j - offset];
            }
            else
            {
                for (int j = size - 1; j >= offset; j--)
                {
                    bits[j] |= bits[j - offset] << shift;
                    if (j - offset - 1 >= 0)
                        bits[j] |= (long)((ulong)bits[j - offset - 1] >> (64 - shift));
                }
            }
        }
    }
}

namespace IAFahim.DP.Optimization
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class KnuthOptimization
    {
        public static long Run(int n, long* dp, long* a, long* opt)
        {
            InitializeDp(n, dp, opt);
            for (int len = 2; len <= n; len++)
            {
                ComputeRow(n, len, dp, a, opt);
            }
            return dp[n - 1];
        }

        private static void InitializeDp(int n, long* dp, long* opt)
        {
            int total = n * n;
            for (int i = 0; i < total; i++) { dp[i] = 0; opt[i] = -1; }
            for (int i = 0; i < n; i++) opt[i * n + i] = i;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void ComputeRow(int n, int len, long* dp, long* a, long* opt)
        {
            for (int i = 0; i + len <= n; i++)
            {
                int j = i + len - 1;
                dp[i * n + j] = FindBestSplit(i, j, n, len, dp, a, opt);
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long FindBestSplit(int i, int j, int n, int len, long* dp, long* a, long* opt)
        {
            long best = long.MaxValue;
            int bestK = -1;
            int rowI = i * n;
            int start = (int)opt[rowI + j - 1];
            int end = (int)opt[(i + 1) * n + j];
            if (start == -1) start = i;
            if (end == -1) end = j - 1;

            long cost = a[j + 1] - a[i]; // Cost(i, j) = a[j+1]-a[i], invariant over k
            int kp1Row = (start + 1) * n;
            for (int k = start; k <= end && k < j; k++, kp1Row += n)
            {
                long val = dp[rowI + k] + dp[kp1Row + j];
                if (val < best) { best = val; bestK = k; }
            }
            opt[rowI + j] = bestK;
            return bestK == -1 ? best : best + cost;
        }
    }

    public static unsafe class LiChaoAddLine
    {
        // Inserts the line y = m*x + b over the integer coordinate domain [x1, x2].
        // Precondition (unchecked): x1 <= x2. The recursion is driven solely by the
        // coordinate domain (a single, consistent subdivision); the index bounds l, r
        // are accepted for API compatibility but are not used for routing.
        // Storage for node N lives in seg[N*2] (slope) and seg[N*2+1] (intercept);
        // children are nodes N*2+1 (left, [x1, midX]) and N*2+2 (right, [midX+1, x2]).
        public static void Run(long* seg, long m, long b, int node, int l, int r, long x1, long x2)
        {
            long midX = x1 + ((x2 - x1) >> 1); // x2 >= x1 invariant => >>1 == /2
            long curMidM = seg[node * 2 + 0], curMidB = seg[node * 2 + 1];

            // Keep the line that is better at the midpoint stored at this node;
            // continue descending with the displaced line. After this block,
            // (curMidM, curMidB) is the line now stored at the node and
            // (m, b) is the displaced line that descends.
            if (m * midX + b < curMidM * midX + curMidB)
            {
                long displacedM = curMidM, displacedB = curMidB;
                curMidM = m;
                curMidB = b;
                seg[node * 2 + 0] = curMidM;
                seg[node * 2 + 1] = curMidB;
                m = displacedM;
                b = displacedB;
            }

            if (x1 == x2) return;
            if (m * x1 + b < curMidM * x1 + curMidB) Run(seg, m, b, node * 2 + 1, l, r, x1, midX);
            else Run(seg, m, b, node * 2 + 2, l, r, midX + 1, x2);
        }
    }
}

namespace IAFahim.DS.Dsu
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class DsuInit
    {
        public static void Run(int* parent, int* size, int n)
        {
            for (int i = 0; i < n; i++)
            {
                parent[i] = i;
                size[i] = 1;
            }
        }
    }

    public static unsafe class DsuFind
    {
        public static int Run(int* parent, int x)
        {
            int root = x;
            while (parent[root] != root)
            {
                root = parent[root];
            }
            return root;
        }

        public static int RunPathCompression(int* parent, int x)
        {
            int root = x;
            while (parent[root] != root) root = parent[root];
            while (parent[x] != root)
            {
                int next = parent[x];
                parent[x] = root;
                x = next;
            }
            return root;
        }
    }

    public static unsafe class DsuUnion
    {
        public static bool Run(int* parent, int* size, int a, int b)
        {
            int ra = DsuFind.Run(parent, a);
            int rb = DsuFind.Run(parent, b);
            if (ra == rb) return false;
            if (size[ra] < size[rb])
            {
                parent[ra] = rb;
                size[rb] += size[ra];
            }
            else
            {
                parent[rb] = ra;
                size[ra] += size[rb];
            }
            return true;
        }
    }

    public static unsafe class DsuSame
    {
        public static bool Run(int* parent, int a, int b)
        {
            return DsuFind.Run(parent, a) == DsuFind.Run(parent, b);
        }
    }

    public static unsafe class DsuSize
    {
        public static int Run(int* parent, int* size, int x)
        {
            return size[DsuFind.Run(parent, x)];
        }
    }

    public static unsafe class DsuRollbackSnapshot
    {
        public static int Run(int* history, int histSize)
        {
            return histSize;
        }
    }

    public static unsafe class DsuRollback
    {
        public static void Run(int* parent, int* size, int* history, int targetHistSize, int* currentHistSize)
        {
            while (*currentHistSize > targetHistSize)
            {
                RollbackStep(parent, size, history, currentHistSize);
            }
        }

        private static void RollbackStep(int* parent, int* size, int* history, int* currentHistSize)
        {
            *currentHistSize -= 3;
            int par = history[*currentHistSize];
            int child = history[*currentHistSize + 1];
            int sz = history[*currentHistSize + 2];
            parent[child] = child;
            size[par] = sz;
        }
    }

    public static unsafe class DsuRollbackUnion
    {
        public static bool Run(int* parent, int* size, int* history, int* histSize, int a, int b)
        {
            int ra = FindSimple(parent, a);
            int rb = FindSimple(parent, b);
            if (ra == rb) return false;
            if (size[ra] < size[rb]) Swap(ref ra, ref rb);

            RecordHistory(history, histSize, ra, rb, size[ra]);
            parent[rb] = ra;
            size[ra] += size[rb];
            return true;
        }

        private static int FindSimple(int* parent, int x)
        {
            while (parent[x] != x) x = parent[x];
            return x;
        }

        private static void Swap(ref int a, ref int b) { int t = a; a = b; b = t; }

        private static void RecordHistory(int* history, int* histSize, int ra, int rb, int sizeRa)
        {
            history[(*histSize)++] = ra;
            history[(*histSize)++] = rb;
            history[(*histSize)++] = sizeRa;
        }
    }

    public static unsafe class DsuBipartiteAdd
    {
        public static bool Run(int* parent, int* parity, int* size, int* hist, int* histSize, int a, int b)
        {
            int ra = FindBipartiteRoot(parent, parity, a, out int pa);
            int rb = FindBipartiteRoot(parent, parity, b, out int pb);
            if (ra == rb) return (pa ^ pb) != 0;

            RecordBipartiteHistory(parent, size, hist, histSize, ra, rb);
            UpdateBipartiteMerge(parent, parity, size, ra, rb, pa, pb);
            return true;
        }

        private static int FindBipartiteRoot(int* parent, int* parity, int x, out int p)
        {
            p = 0;
            while (parent[x] != x) { p ^= parity[x]; x = parent[x]; }
            return x;
        }

        private static void RecordBipartiteHistory(int* parent, int* size, int* hist, int* histSize, int ra, int rb)
        {
            hist[(*histSize)++] = ra;
            hist[(*histSize)++] = rb;
            hist[(*histSize)++] = size[ra];
            hist[(*histSize)++] = size[rb];
            hist[(*histSize)++] = parent[ra];
            hist[(*histSize)++] = parent[rb];
        }

        private static void UpdateBipartiteMerge(int* parent, int* parity, int* size, int ra, int rb, int pa, int pb)
        {
            if (size[ra] > size[rb])
            {
                parent[rb] = ra;
                parity[rb] = pa ^ pb ^ 1;
                size[ra] += size[rb];
            }
            else
            {
                parent[ra] = rb;
                parity[ra] = pa ^ pb ^ 1;
                size[rb] += size[ra];
            }
        }
    }

    public static unsafe class DsuParityFind
    {
        public static int Run(int* parent, int* parity, int x)
        {
            int root = x;
            int acc = 0;
            while (parent[root] != root)
            {
                acc ^= parity[root];
                root = parent[root];
            }
            int cur = x;
            int curParity = 0;
            while (parent[cur] != root)
            {
                int next = parent[cur];
                int oldPar = parity[cur];
                parity[cur] = acc ^ curParity;
                curParity ^= oldPar;
                parent[cur] = root;
                cur = next;
            }
            return root;
        }
    }

    public static unsafe class DsuParityUnion
    {
        public static bool Run(int* parent, int* parity, int a, int b, int w)
        {
            int ra = DsuParityFind.Run(parent, parity, a);
            int rb = DsuParityFind.Run(parent, parity, b);
            if (ra == rb)
            {
                return ((parity[a] ^ parity[b]) & 1) == (w & 1);
            }
            if (parent[ra] == ra)
            {
                parent[ra] = rb;
                parity[ra] = parity[a] ^ parity[b] ^ w;
            }
            else
            {
                parent[rb] = ra;
                parity[rb] = parity[a] ^ parity[b] ^ w;
            }
            return true;
        }
    }

    public static unsafe class SmallToLargeMerge
    {
        public static void Run(int* parent, int* heavy, int n)
        {
            for (int i = 0; i < n; i++)
                heavy[i] = -1;
        }
    }
}

namespace IAFahim.DS.Fenwick
{
    using System.Runtime.CompilerServices;

    public static unsafe class PersistentFenwickUpdate
    {
        public static int Run(int* leftChild, int* rightChild, int* sumArr, int* allocCount,
            int prev, int lIn, int rIn, int idx, int val)
        {
            int first = ++(*allocCount);
            int curPrev = prev;
            int l = lIn, r = rIn;
            int node = first;
            bool firstNode = true;
            while (true)
            {
                leftChild[node] = curPrev != 0 ? leftChild[curPrev] : 0;
                rightChild[node] = curPrev != 0 ? rightChild[curPrev] : 0;
                sumArr[node] = (curPrev != 0 ? sumArr[curPrev] : 0) + val;

                if (l == r)
                {
                    if (!firstNode) break;
                    return node;
                }

                int mid = l + ((r - l) >> 1);
                int child = ++(*allocCount);
                if (idx <= mid)
                {
                    leftChild[node] = child;
                    curPrev = curPrev != 0 ? leftChild[curPrev] : 0;
                    r = mid;
                }
                else
                {
                    rightChild[node] = child;
                    curPrev = curPrev != 0 ? rightChild[curPrev] : 0;
                    l = mid + 1;
                }
                node = child;
                firstNode = false;
            }
            return first;
        }
    }

    public static unsafe class PersistentFenwickQuery
    {
        public static int Run(int* leftChild, int* rightChild, int* sumArr,
            int node, int l, int r, int ql, int qr)
        {
            if (node == 0 || qr < l || ql > r) return 0;
            if (ql <= l && r <= qr) return sumArr[node];
            int mid = l + ((r - l) >> 1);
            return Run(leftChild, rightChild, sumArr, leftChild[node], l, mid, ql, qr) +
                   Run(leftChild, rightChild, sumArr, rightChild[node], mid + 1, r, ql, qr);
        }
    }
}

namespace IAFahim.DS.Fenwick
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Fenwick
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void AddInt64(long* bit, int n, int idx, long val)
        {
            for (idx += 1; idx <= n; idx += idx & -idx)
                bit[idx] += val;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long SumInt64(long* bit, int idx)
        {
            long res = 0;
            for (idx += 1; idx > 0; idx -= idx & -idx)
                res += bit[idx];
            return res;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long RangeSumInt64(long* bit, int l, int r)
        {
            if (l > r) return 0;
            long res = SumInt64(bit, r);
            if (l == 0) return res;
            return res - SumInt64(bit, l - 1);
        }

        /// <summary>
        /// Lower bound: finds smallest index i where prefix sum [0, i] >= target.
        /// Returns n if target exceeds total sum.
        /// Assumes all values are non-negative.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int LowerBoundInt64(long* bit, int n, long target)
        {
            if (target <= 0) return 0;
            int idx = 0;
            int bitMask = 1;
            while ((bitMask << 1) <= n) bitMask <<= 1;
            for (; bitMask != 0; bitMask >>= 1)
            {
                int next = idx + bitMask;
                if (next <= n && bit[next] < target)
                {
                    idx = next;
                    target -= bit[next];
                }
            }
            return idx;
        }

        /// <summary>
        /// Upper bound: finds smallest index i where prefix sum [0, i] > target.
        /// Returns n if target >= total sum.
        /// Assumes all values are non-negative.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int UpperBoundInt64(long* bit, int n, long target)
        {
            if (target < 0) return 0;
            long total = SumInt64(bit, n - 1); // total sum of array [0..n-1]
            if (target >= total) return n;
            int idx = 0;
            int bitMask = 1;
            while ((bitMask << 1) <= n) bitMask <<= 1;
            for (; bitMask != 0; bitMask >>= 1)
            {
                int next = idx + bitMask;
                if (next <= n && bit[next] <= target)
                {
                    idx = next;
                    target -= bit[next];
                }
            }
            return idx;
        }
    }
}

