    public static unsafe class FenwickSum
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Run(int* bit, int idx)
        {
            int res = 0;
            for (idx += 1; idx > 0; idx -= idx & -idx)
                res += bit[idx];
            return res;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long RunLong(long* bit, int idx)
        {
            long res = 0;
            for (idx += 1; idx > 0; idx -= idx & -idx)
                res += bit[idx];
