    using System.Runtime.CompilerServices;
    using System.Threading;

    public struct SpinLock
    {
        private int @lock;

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public void Acquire()
        {
            for (;;)
            {
                if (Interlocked.CompareExchange(ref this.@lock, 1, 0) == 0)
                {
                    return;
                }

                while (Volatile.Read(ref this.@lock) == 1)
                {
                }
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public bool TryAcquire()
        {
            return Volatile.Read(ref this.@lock) == 0 && Interlocked.CompareExchange(ref this.@lock, 1, 0) == 0;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public bool TryAcquire(bool spin)
        {
            if (spin)
            {
                this.Acquire();
                return true;
            }

            return this.TryAcquire();
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public void Release()
        {
            Volatile.Write(ref this.@lock, 0);
        }
    }
}

namespace IAFahim.DS.FixedCollections
{
    using System;
    using System.Diagnostics;
    using System.Runtime.CompilerServices;
    using Unity.Collections.LowLevel.Unsafe;

    public unsafe struct FixedBitMask<T>
        where T : unmanaged
    {
        private const int Idx = 3;
        private const int Shift = (1 << Idx) - 1;

        private T data;

        public int Length => UnsafeUtility.SizeOf<T>() << 3;

        public void Set(int pos, bool value)
        {
            this.CheckArgs(pos, 1);

            fixed (T* t = &this.data)
            {
                byte* ptr = (byte*)t;

                int idx = pos >> Idx;
                int shift = pos & Shift;
                byte mask = (byte)(1 << shift);

                byte bits = (byte)((ptr[idx] & ~mask) | (-AsByte(value) & mask));
                ptr[idx] = bits;
            }
        }

        public bool IsSet(int pos)
        {
            this.CheckArgs(pos, 1);

            fixed (T* t = &this.data)
            {
                byte* ptr = (byte*)t;

                int idx = pos >> Idx;
                int shift = pos & Shift;
                byte mask = (byte)(1 << shift);
                return (ptr[idx] & mask) != 0;
            }
        }

        public void Reset()
        {
            fixed (T* t = &this.data)
            {
                UnsafeUtility.MemClear(t, UnsafeUtility.SizeOf<T>());
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int AsByte(bool value)
        {
            return value ? 1 : 0;
        }

        [Conditional("ENABLE_UNITY_COLLECTIONS_CHECKS")]
        private void CheckArgs(int pos, int numBits)
        {
            if (pos < 0 || pos >= this.Length || numBits < 1)
            {
                throw new ArgumentException();
            }
        }
    }
}

namespace IAFahim.DS.FixedCollections
{
    using System;
    using Unity.Collections;
    using Unity.Collections.LowLevel.Unsafe;

    public readonly struct UnsafeListPool<T> : IDisposable
        where T : unmanaged
    {
        private readonly UnmanagedPool<UnsafeList<T>> pool;

        public UnsafeListPool(int capacity, Allocator allocator = Allocator.Persistent)
        {
            this.pool = new UnmanagedPool<UnsafeList<T>>(capacity, allocator);
        }

        public bool IsCreated => this.pool.IsCreated;

        public void Dispose()
        {
            UnsafeList<T> list;
            while (this.pool.TryGet(out list))
            {
                list.Dispose();
            }

            this.pool.Dispose();
        }

        public bool TryAdd(UnsafeList<T> element)
        {
            return this.pool.TryAdd(element);
        }

        public bool TryGet(out UnsafeList<T> element)
        {
            return this.pool.TryGet(out element);
        }

        public UnsafeList<T> GetOrCreate(int minimumCapacity, AllocatorManager.AllocatorHandle listAllocator)
        {
            UnsafeList<T> list;
            if (this.TryGet(out list))
            {
                return list;
            }

            return new UnsafeList<T>(minimumCapacity, listAllocator);
        }

        public void ReturnOrDispose(UnsafeList<T> list)
        {
            if (this.TryAdd(list))
            {
                return;
            }

            if (list.IsCreated)
            {
                list.Dispose();
            }
        }
    }
}

namespace IAFahim.DS.FixedCollections
{
    using System;
    using Unity.Burst;
    using Unity.Collections;
    using Unity.Collections.LowLevel.Unsafe;
    using BovineLabs.Core.Memory;

    [NativeContainer]
    public unsafe struct NativeLinearCongruentialGenerator : IDisposable
    {
        private const int Multiplier = 134775813;
        private const int Increment = 1;
        private const int Modulus = int.MaxValue;

        [NativeDisableUnsafePtrRestriction]
        private int* current;

#if ENABLE_UNITY_COLLECTIONS_CHECKS
        private AtomicSafetyHandle m_Safety;
        private static readonly SharedStatic<int> s_staticSafetyId = SharedStatic<int>.GetOrCreate<NativeLinearCongruentialGenerator>();
#endif

        private AllocatorManager.AllocatorHandle allocatorLabel;

        public NativeLinearCongruentialGenerator(int seed, Allocator allocator)
        {
            Allocate(allocator, out this);
            *this.current = seed;
        }

        private static void Allocate(AllocatorManager.AllocatorHandle allocator, out NativeLinearCongruentialGenerator reference)
        {
            CollectionHelper.CheckAllocator(allocator);

            reference = default;
            reference.current = (int*)Unmanaged.Allocate((long)UnsafeUtility.SizeOf<int>(), UnsafeUtility.AlignOf<int>(), allocator);
            reference.allocatorLabel = allocator;

#if ENABLE_UNITY_COLLECTIONS_CHECKS
            reference.m_Safety = CollectionHelper.CreateSafetyHandle(allocator);

            CollectionHelper.SetStaticSafetyId<NativeLinearCongruentialGenerator>(ref reference.m_Safety, ref s_staticSafetyId.Data);
            AtomicSafetyHandle.SetBumpSecondaryVersionOnScheduleWrite(reference.m_Safety, true);
#endif
        }

        public void Dispose()
        {
#if ENABLE_UNITY_COLLECTIONS_CHECKS
            CollectionHelper.DisposeSafetyHandle(ref this.m_Safety);
#endif
            Unmanaged.Free(this.current, this.allocatorLabel);

            this.current = null;
        }

        public int Next()
        {
#if ENABLE_UNITY_COLLECTIONS_CHECKS
            AtomicSafetyHandle.CheckWriteAndThrow(this.m_Safety);
#endif

            int x = *this.current;
            int x1 = ((Multiplier * x) + Increment) & Modulus;
            *this.current = x1;

            return *this.current;
        }
    }
}

namespace IAFahim.DS.FixedCollections
{
    using System;
    using System.Runtime.CompilerServices;
    using Unity.Collections;
    using Unity.Collections.LowLevel.Unsafe;
    using Unity.Mathematics;
    using BovineLabs.Core.Memory;

    public readonly unsafe struct UnmanagedPool<T> : IDisposable
        where T : unmanaged
    {
        private readonly int capacity;
        private readonly Allocator allocator;

        [NativeDisableUnsafePtrRestriction]
        private readonly T* buffer;

        [NativeDisableUnsafePtrRestriction]
        private readonly int* length;

        [NativeDisableUnsafePtrRestriction]
        private readonly SpinLock* spinner;

        public UnmanagedPool(int capacity, Allocator allocator = Allocator.Persistent)
        {
            capacity = GetCapacity(capacity);
            this.capacity = capacity;
            this.allocator = allocator;

            this.buffer = (T*)Unmanaged.Allocate((long)sizeof(T) * capacity, UnsafeUtility.AlignOf<T>(), allocator);
            this.length = (int*)Unmanaged.Allocate((long)sizeof(int), UnsafeUtility.AlignOf<int>(), allocator);
            *this.length = 0;
            this.spinner = (SpinLock*)Unmanaged.Allocate((long)sizeof(SpinLock), UnsafeUtility.AlignOf<SpinLock>(), allocator);
            *this.spinner = default;
        }

        public bool IsCreated => this.buffer != null;

        public void Dispose()
        {
            Unmanaged.Free(this.buffer, this.allocator);
            Unmanaged.Free(this.length, this.allocator);
            Unmanaged.Free(this.spinner, this.allocator);
        }

        public bool TryAdd(T element)
        {
            this.spinner->Acquire();

            if (*this.length < this.capacity)
            {
                this.buffer[*this.length] = element;
                *this.length += 1;
                this.spinner->Release();
                return true;
            }

            this.spinner->Release();
            return false;
        }

        public bool TryGet(out T element)
        {
            this.spinner->Acquire();

            if (*this.length > 0)
            {
                *this.length -= 1;
                element = this.buffer[*this.length];
                this.spinner->Release();
                return true;
            }

            element = default;
            this.spinner->Release();
            return false;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int GetCapacity(int newCapacity)
        {
            newCapacity = math.max(newCapacity, CollectionHelper.CacheLineSize / sizeof(T));
            newCapacity = math.ceilpow2(newCapacity);
            return newCapacity;
        }
    }
}

namespace IAFahim.DS.FixedCollections
{
    using System;
    using System.Diagnostics.Contracts;
    using System.Runtime.CompilerServices;
    using Unity.Collections.LowLevel.Unsafe;

    public unsafe struct FixedHashMap<TKey, TValue, TCapacity>
        where TKey : unmanaged, IEquatable<TKey>
        where TValue : unmanaged
        where TCapacity : unmanaged
    {
        private readonly TCapacity data;
        private readonly int sizeOfValueT;

        public FixedHashMap(TCapacity data)
        {
            this.data = data;
            this.sizeOfValueT = sizeof(TValue);
            this.Count = 0;
            this.Capacity = CalcCapacity();

            long totalHashesSizeInBytes = (long)UnsafeUtility.SizeOf<uint>() * this.Capacity;
            UnsafeUtility.MemSet(this.Ptr, 0xff, totalHashesSizeInBytes);
        }

        public int Capacity { get; }

        public int Count { get; private set; }

        private uint* Ptr
        {
            get
            {
                fixed (TCapacity* key = &this.data)
                {
                    return (uint*)key;
                }
            }
        }

        private int* NumItems => (int*)(this.Ptr + this.Capacity);

        private TKey* Keys => (TKey*)(this.Ptr + (this.Capacity * 2));

        public bool TryAdd(TKey key, TValue item)
        {
            int idx = this.TryAdd(key);
            if (idx != -1)
            {
                this.GetElementAt(idx) = item;
                return true;
            }

            return false;
        }

        [Pure]
        public bool TryGetValue(TKey key, out TValue item)
        {
            int idx = this.Find(key);

            if (idx != -1)
            {
                item = this.GetElementAt(idx);
                return true;
            }

            item = default;
            return false;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int CalcCapacity()
        {
            int sizeOfElement = sizeof(uint) + sizeof(uint) + sizeof(TValue) + sizeof(TKey);
            int capacity = sizeof(TCapacity) / sizeOfElement;
            return capacity;
        }

        private int TryAdd(in TKey key)
        {
            uint hash = this.Hash(key);
            int firstIdx = this.GetFirstIdx(hash);
            int idx = firstIdx;

            do
            {
                uint current = this.Ptr[idx];

                if (current == uint.MaxValue)
                {
                    this.Ptr[idx] = hash;
                    this.GetKeyAt(idx) = key;
                    this.Count++;

                    this.NumItems[firstIdx] += 1;

                    return idx;
                }

                if (current == hash && this.GetKeyAt(idx).Equals(key))
                {
                    return -1;
                }

                idx = (idx + 1) % this.Capacity;
            }
            while (idx != firstIdx);

            return -1;
        }

        private int Find(in TKey key)
        {
            uint hash = this.Hash(key);
            int firstIdx = this.GetFirstIdx(hash);
            int num = this.NumItems[firstIdx];
            int idx = firstIdx;

            do
            {
                if (num == 0)
                {
                    return -1;
                }

                if (this.Ptr[idx] == hash)
                {
                    if (this.GetKeyAt(idx).Equals(key))
                    {
                        return idx;
                    }

                    num--;
                }

                idx = (idx + 1) % this.Capacity;
            }
            while (idx != firstIdx);

            return -1;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private uint Hash(in TKey key)
        {
            uint hash = (uint)key.GetHashCode();
            return hash == uint.MaxValue ? 0 : hash;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private int GetFirstIdx(uint hash)
        {
            return (int)(hash % (uint)this.Capacity);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private ref TKey GetKeyAt(int idx)
        {
            return ref this.Keys[idx];
        }

        private ref TValue GetElementAt(int idx)
        {
            return ref *(TValue*)this.GetElementAt(this.Ptr, this.Capacity, idx);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private void* GetElementAt(void* src, int capacity, int idx)
        {
            byte* ptr = (byte*)src;
            ptr += capacity * (sizeof(uint) + sizeof(int) + sizeof(TKey));
            ptr += idx * this.sizeOfValueT;

            return ptr;
        }
    }
}

