namespace IAFahim.DS.Heap
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class HeapPush
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int Parent(int i) => (i - 1) >> 1;

        public static void Run<T>(T* ptr, int len, T val) where T : unmanaged, IComparable<T>
        {
            int i = len;
            ptr[i] = val;
            while (i > 0)
            {
                int p = Parent(i);
                if (ptr[p].CompareTo(ptr[i]) <= 0) break;
                T tmp = ptr[p];
                ptr[p] = ptr[i];
                ptr[i] = tmp;
                i = p;
            }
        }
    }

    public static unsafe class HeapPop
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int Left(int i) => (i << 1) + 1;

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int Right(int i) => (i << 1) + 2;

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void Swap<T>(T* a, T* b) where T : unmanaged { T t = *a; *a = *b; *b = t; }

        public static T Run<T>(T* ptr, int len) where T : unmanaged, IComparable<T>
        {
            T result = ptr[0];
            ptr[0] = ptr[len - 1];
            HeapFix.Run(ptr, 0, len - 1);
            return result;
        }
    }

    public static unsafe class HeapFix
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int Left(int i) => (i << 1) + 1;

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int Right(int i) => (i << 1) + 2;

        public static void Run<T>(T* ptr, int i, int len) where T : unmanaged, IComparable<T>
        {
            while (true)
            {
                int smallest = i;
                int l = Left(i);
                int r = Right(i);
                if (l < len && ptr[l].CompareTo(ptr[smallest]) < 0) smallest = l;
                if (r < len && ptr[r].CompareTo(ptr[smallest]) < 0) smallest = r;
                if (smallest == i) break;
                T tmp = ptr[i];
                ptr[i] = ptr[smallest];
                ptr[smallest] = tmp;
                i = smallest;
            }
        }
    }

    public static unsafe class HeapRemove
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int Parent(int i) => (i - 1) >> 1;

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int Left(int i) => (i << 1) + 1;

        public static void Run<T>(T* ptr, int i, int len) where T : unmanaged, IComparable<T>
        {
            ptr[i] = ptr[len - 1];
            int cur = i;
            while (cur > 0)
            {
                int p = Parent(cur);
                if (ptr[p].CompareTo(ptr[cur]) <= 0) break;
                T tmp = ptr[p];
                ptr[p] = ptr[cur];
                ptr[cur] = tmp;
                cur = p;
            }
            int n = len - 1;
            if (cur != i) return;
            int l = Left(cur);
            while (l < n)
            {
                int smallest = cur;
                if (ptr[l].CompareTo(ptr[smallest]) < 0) smallest = l;
                int r = l + 1;
                if (r < n && ptr[r].CompareTo(ptr[smallest]) < 0) smallest = r;
                if (smallest == cur) break;
                T tmp = ptr[cur];
                ptr[cur] = ptr[smallest];
                ptr[smallest] = tmp;
                cur = smallest;
                l = Left(cur);
            }
        }
    }

    public static unsafe class DequePush
    {
        public static void PushFrontInt32(int* deque, int* front, int* back, int cap, int val)
        {
            *front = (*front - 1 + cap) % cap;
            deque[*front] = val;
        }

        public static void PushBackInt32(int* deque, int* front, int* back, int cap, int val)
        {
            deque[*back] = val;
            *back = (*back + 1) % cap;
        }
    }

    public static unsafe class DequePop
    {
        public static int PopFrontInt32(int* deque, int* front, int* back, int cap)
        {
            int val = deque[*front];
            *front = (*front + 1) % cap;
            return val;
        }

        public static int PopBackInt32(int* deque, int* front, int* back, int cap)
        {
            *back = (*back - 1 + cap) % cap;
            return deque[*back];
        }
    }

    public static unsafe class MonotonicQueueMin
    {
        public static void Run(int* src, int* dst, int len, int windowSize)
        {
            if (len == 0 || windowSize == 0) return;
            int cap = (windowSize < len ? windowSize : len) + 1;
            int* deque = stackalloc int[cap];
            int front = 0, back = 0;
            for (int i = 0; i < len; i++)
            {
                while (front < back && src[deque[back - 1]] >= src[i]) back--;
                deque[back++] = i;
                if (deque[front] <= i - windowSize) front++;
                if (i >= windowSize - 1)
                    dst[i - windowSize + 1] = src[deque[front]];
            }
        }
    }

    public static unsafe class MonotonicQueuePush
    {
        public static void MinInt32(int* mono, int* size, int val)
        {
            while (*size > 0 && mono[*size - 1] >= val) (*size)--;
            mono[*size] = val;
            (*size)++;
        }
    }

    public static unsafe class MonotonicStackProcess
    {
        public static int NextGreaterInt32(int* src, int* dst, int len)
        {
            if (len == 0) return 0;
            int* stack = stackalloc int[len];
            int top = 0;
            for (int i = 0; i < len; i++)
            {
                while (top > 0 && src[stack[top - 1]] < src[i])
                {
                    dst[stack[--top]] = i;
                }
                stack[top++] = i;
            }
            int count = top;
            return count;
        }
    }
}

namespace IAFahim.DS.HilbertOrder
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class HilbertOrder
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Run(long x, long y, int pow, int rot)
        {
            x &= (1L << pow) - 1; y &= (1L << pow) - 1;
            int rotSeed = rot & 3;
            long d = 0;
            for (int i = pow; i > 0; i--)
            {
                int rx = (int)((x >> (i - 1)) & 1), ry = (int)((y >> (i - 1)) & 1);
                int seg = ((3 * rx) ^ ry) ^ rotSeed;
                d += (1L << (2 * i - 2)) * seg;
                if (ry == 0) RotateHilbert(ref x, ref y, rx, i);
            }
            return d;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Encode(long x, long y, int logN)
        {
            x &= (1L << logN) - 1; y &= (1L << logN) - 1;
            long d = 0;
            for (int i = logN; i > 0; i--)
            {
                int rx = (int)((x >> (i - 1)) & 1), ry = (int)((y >> (i - 1)) & 1);
                d += (1L << (2 * i - 2)) * ((3 * rx) ^ ry);
                if (ry == 0) RotateHilbert(ref x, ref y, rx, i);
            }
            return d;
        }

        public static long SwappedEncode(long x, long y, int logN) => Encode(Math.Min(x, y), Math.Max(x, y), logN);

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void RotateHilbert(ref long x, ref long y, int rx, int i)
        {
            if (rx == 1) { long mask = (1L << i) - 1; x = mask - x; y = mask - y; }
            long t = x; x = y; y = t;
        }
    }

    public static unsafe class GilbertOrder
    {
        public static long Encode(long x, long y, int w, int h)
        {
            if (w <= 0 || h <= 0) return 0;
            if (w >= h) return EncodeRecursive(x, y, 0, 0, w, 0, 0, h);
            return EncodeRecursive(x, y, 0, 0, 0, h, w, 0);
        }

        private static long EncodeRecursive(long x, long y, long ax, long ay, long bx, long by, long cx, long cy)
        {
            long w = Math.Abs(bx + cx), h = Math.Abs(by + cy);
            if (w <= 1 && h <= 1) return 0;
            // Placeholder for real Gilbert curve logic
            return x * h + y;
        }
    }

    public static unsafe class BlockOrder
    {
        public static long Encode(int l, int r, int blockSize)
        {
            int block = l / blockSize;
            long off = (block & 1) != 0 ? (long)(int.MaxValue - 1 - r) : r;
            return (long)block * int.MaxValue + off;
        }

        public static void Decode(long code, int n, int blockSize, int* l, int* r)
        {
            int block = (int)(code / int.MaxValue);
            long off = code % int.MaxValue;
            *l = block * blockSize;
            *r = (block & 1) != 0 ? (int)(int.MaxValue - 1 - off) : (int)off;
        }
    }
}

namespace IAFahim.DS.LinkCut
{
    using System;
    using System.Runtime.CompilerServices;
    using System.Runtime.InteropServices;

    [StructLayout(LayoutKind.Sequential)]
    public unsafe struct LctNode
    {
        public int Index;
        public long Value;
        public long PathSum;
        public bool Rev;
        public LctNode* Left;
        public LctNode* Right;
        public LctNode* Parent;
    }

    public static unsafe class LinkCut
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void Update(LctNode* x)
        {
            x->PathSum = x->Value;
            if (x->Left != null)
                x->PathSum += x->Left->PathSum;
            if (x->Right != null)
                x->PathSum += x->Right->PathSum;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void Push(LctNode* x)
        {
            if (x->Rev)
            {
                LctNode* tmp = x->Left;
                x->Left = x->Right;
                x->Right = tmp;
                if (x->Left != null)
                    x->Left->Rev = !x->Left->Rev;
                if (x->Right != null)
                    x->Right->Rev = !x->Right->Rev;
                x->Rev = false;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool IsRoot(LctNode* x)
        {
            LctNode* p = x->Parent;
            if (p == null) return true;
            return p->Left != x && p->Right != x;
        }

        private static void Rotate(LctNode* x)
        {
            if (x == null || x->Parent == null) return;
            LctNode* p = x->Parent;
            LctNode* g = p->Parent;
            if (p->Left == x)
            {
                p->Left = x->Right;
                if (x->Right != null)
                    x->Right->Parent = p;
                x->Right = p;
            }
            else
            {
                p->Right = x->Left;
                if (x->Left != null)
                    x->Left->Parent = p;
                x->Left = p;
            }
            p->Parent = x;
            x->Parent = g;
            if (g != null)
            {
                if (g->Left == p)
                    g->Left = x;
                else if (g->Right == p)
                    g->Right = x;
            }
            Update(p);
            Update(x);
        }

        private static void PushTo(LctNode* x)
        {
            if (!IsRoot(x))
                PushTo(x->Parent);
            Push(x);
        }

        private static void Splay(LctNode* x)
        {
            PushTo(x);
            while (!IsRoot(x))
            {
                LctNode* p = x->Parent;
                LctNode* g = p->Parent;
                if (!IsRoot(p))
                {
                    if ((p->Left == x) != (g->Left == p))
                        Rotate(x);
                    else
                        Rotate(p);
                }
                Rotate(x);
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Access(LctNode* x)
        {
            LctNode* last = null;
            while (x != null)
            {
                Splay(x);
                x->Right = last;
                Update(x);
                last = x;
                x = x->Parent;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void MakeRoot(LctNode* x)
        {
            Access(x);
            Splay(x);
            x->Rev = !x->Rev;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static LctNode* FindRoot(LctNode* x)
        {
            Access(x);
            Splay(x);
            while (true)
            {
                Push(x);
                if (x->Left == null) break;
                x = x->Left;
            }
            Splay(x);
            return x;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Link(LctNode* x, LctNode* y)
        {
            MakeRoot(x);
            x->Parent = y;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Cut(LctNode* x, LctNode* y)
        {
            MakeRoot(x);
            Access(y);
            Splay(y);
            if (y->Left == x)
            {
                x->Parent = null;
                y->Left = null;
                Update(y);
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Query(LctNode* x, LctNode* y)
        {
            MakeRoot(x);
            Access(y);
            Splay(y);
            return y->PathSum;
        }
    }
}
